/* GERADO por scripts/dividir-dados.js — não edite à mão.
   A fonte editável continua sendo js/data*.js. */
registrarDetalhes({"IN-001":{"cognitivo":{"motivo":"Troca de rótulos entre phishing e ransomware — o padrão nº 1 de Informática na banca.","mede":"Conceitos de ameaças cibernéticas.","pegadinhaDesc":"A definição é perfeita — de OUTRO golpe (phishing).","ondeErra":"Valida a definição correta sem conferir o nome.","palavraCritica":"ransomware × phishing","tecnica":"Em Informática, a banca quase nunca erra a definição: ela troca o TERMO definido.","regraMental":"RANSOM = resgate (sequestro/cifração de dados). PHISHING = pescaria (isca por mensagem falsa)."},"comentario":{"resolucao":"ERRADO. A definição apresentada é de PHISHING. Ransomware é o malware que cifra/bloqueia dados do sistema e exige pagamento de resgate (ransom) para a liberação.","fundamento":"Cartilha de Segurança CERT.br — conceitos de códigos maliciosos e golpes.","macete":"Ransom = resgate em inglês. Phishing = fishing (pescar a vítima).","erroComum":"Julgar a qualidade da definição e não o pareamento nome↔definição.","comoBancaPensa":"Definição impecável + rótulo errado: o mesmo DNA da troca de conceitos jurídica."}},"IN-002":{"cognitivo":{"motivo":"Cobrar a distinção incremental × diferencial.","mede":"Estratégias de cópia de segurança.","pegadinhaDesc":"O 'somente' ativa o alarme, mas aqui é tecnicamente correto.","ondeErra":"Marca E por reflexo do 'somente' ou por confundir com becape diferencial.","palavraCritica":"desde o último becape (qualquer tipo)","tecnica":"Incremental: referência = último becape de QUALQUER tipo. Diferencial: referência = último becape COMPLETO.","regraMental":"Incremental = incrementos pequenos, restauração trabalhosa. Diferencial = cresce a cada dia, restauração simples."},"comentario":{"resolucao":"CERTO. O becape incremental copia apenas o que mudou desde o último becape (completo ou incremental), sendo o mais econômico em espaço/tempo de cópia — ao custo de restauração mais complexa (exige o completo + toda a cadeia de incrementais).","fundamento":"Fundamentos de infraestrutura e segurança de TI.","macete":"Incremental olha para ONTEM. Diferencial olha para o ÚLTIMO COMPLETO.","erroComum":"Trocar as referências dos dois tipos.","comoBancaPensa":"Usa 'somente' verdadeiro para punir o candidato que decora heurística sem conteúdo."}},"IN-003":{"cognitivo":{"motivo":"Cobrar o comportamento de exclusão definitiva.","mede":"Operações básicas do Windows.","pegadinhaDesc":"Descreve o comportamento do Delete comum atribuindo-o ao Shift+Delete.","ondeErra":"Não pratica o atalho e responde por suposição.","palavraCritica":"Shift","tecnica":"Shift+Delete = exclusão direta, sem Lixeira (recuperável apenas por software forense).","regraMental":"Shift 'pula' a Lixeira."},"comentario":{"resolucao":"ERRADO. Shift + Delete exclui o arquivo diretamente, sem passar pela Lixeira — não há restauração pelo caminho comum. (Detalhe de prova policial: dados assim excluídos ainda podem ser recuperados por técnicas periciais até serem sobrescritos.)","fundamento":"Documentação do Microsoft Windows.","macete":"Delete = Lixeira. Shift+Delete = sem escala.","erroComum":"Assumir que toda exclusão passa pela Lixeira.","comoBancaPensa":"Atribui a um comando o efeito de outro — 'troca de conceitos' aplicada à informática básica."}},"TI-001":{"cognitivo":{"motivo":"Troca de rótulos entre os dois grandes modelos criptográficos.","mede":"Fundamentos de criptografia (item 4 de Segurança Cibernética).","pegadinhaDesc":"A definição é perfeita — da criptografia SIMÉTRICA.","ondeErra":"Valida a definição correta sem conferir o nome.","palavraCritica":"única chave","tecnica":"Assimétrica = PAR de chaves (pública cifra, privada decifra). Simétrica = uma chave só, compartilhada.","regraMental":"A-ssimétrica = 2 chaves (o 'A' de Ambas). Simétrica = Só uma."},"comentario":{"resolucao":"ERRADO. A definição corresponde à criptografia SIMÉTRICA (ex.: AES). Na assimétrica (ex.: RSA), cada parte possui um par de chaves matematicamente relacionadas: a pública, distribuível, e a privada, secreta — o que cifra com uma, decifra-se com a outra.","fundamento":"Fundamentos de criptografia — modelos simétrico e assimétrico.","macete":"Assinatura digital usa a assimétrica: privada assina, pública verifica.","erroComum":"Julgar a qualidade da definição e não o pareamento nome↔definição.","comoBancaPensa":"Regra do rótulo: a banca quase nunca erra a definição — troca o termo definido."}},"TI-002":{"cognitivo":{"motivo":"Distinguir detecção (IDS) de prevenção (IPS) — item 3.1/9 do edital.","mede":"Soluções de segurança de rede.","pegadinhaDesc":"Atribui ao IDS a ação ativa que caracteriza o IPS.","ondeErra":"Trata os dois como sinônimos por virem sempre juntos ('IDS/IPS').","palavraCritica":"Detection × Prevention","tecnica":"IDS = sensor passivo: detecta e ALERTA. IPS = inline ativo: detecta e BLOQUEIA.","regraMental":"D de Detectar (avisa). P de Prevenir (barra)."},"comentario":{"resolucao":"ERRADO. O IDS é ferramenta de DETECÇÃO: monitora o tráfego e gera alertas, sem intervir no fluxo. Quem atua inline bloqueando pacotes maliciosos automaticamente é o IPS (Intrusion Prevention System).","fundamento":"Fundamentos de segurança de redes — arquiteturas IDS/IPS.","macete":"IDS é a câmera de segurança; IPS é a cancela.","erroComum":"Assumir que detectar implica bloquear.","comoBancaPensa":"Par de siglas irmãs = alvo clássico de inversão de atribuições."}},"TI-003":{"cognitivo":{"motivo":"Conceito nuclear de VPN, cobrado de forma direta pela banca.","mede":"Segurança de rede (item 3.1).","pegadinhaDesc":"Item conceitual correto — a banca alterna itens limpos para calibrar.","ondeErra":"Procura erro inexistente no exemplo do aeroporto.","palavraCritica":"mesmo sobre redes públicas","tecnica":"VPN = privacidade construída POR CIMA de rede pública, via criptografia (tunelamento).","regraMental":"VPN: cano blindado dentro de rio aberto."},"comentario":{"resolucao":"CERTO. A VPN cria um túnel lógico cifrado entre as extremidades, de modo que os dados trafegam protegidos ainda que a infraestrutura subjacente seja pública e insegura. É prática recomendada para acesso remoto corporativo.","fundamento":"Fundamentos de redes — tunelamento e criptografia (IPsec, SSL/TLS).","macete":"Wi-Fi público sem VPN = cartão-postal; com VPN = carta lacrada.","erroComum":"Achar que 'rede pública' tornaria a afirmação falsa.","comoBancaPensa":"Itens certos de conceito puro premiam quem estuda o básico com precisão."}},"TI-004":{"cognitivo":{"motivo":"Distinção entre dado pessoal e dado pessoal sensível — coração da LGPD em prova.","mede":"Art. 5º, I e II, da LGPD.","pegadinhaDesc":"O CPF 'parece' sensível por ser importante — mas o rol legal é específico.","ondeErra":"Confunde relevância prática com a categoria jurídica 'sensível'.","palavraCritica":"rol do art. 5º, II","tecnica":"Sensível = origem racial/étnica, convicção religiosa, opinião política, filiação sindical, saúde, vida sexual, genético, biométrico.","regraMental":"Sensível é o que expõe QUEM VOCÊ É (crença, corpo, saúde) — não o número que te identifica."},"comentario":{"resolucao":"ERRADO. O CPF é dado pessoal comum (identifica a pessoa natural — art. 5º, I). Dado sensível é o rol do art. 5º, II: origem racial ou étnica, convicção religiosa, opinião política, filiação a sindicato ou organização religiosa/filosófica/política, saúde, vida sexual, dado genético ou biométrico.","fundamento":"Lei 13.709/2018, art. 5º, I e II.","macete":"Sensível: RAÇA-FÉ-POLÍTICA-SINDICATO-SAÚDE-SEXO-GENE-BIOMETRIA. Fora da lista, é comum.","erroComum":"Classificar como sensível todo dado 'importante' (CPF, renda, endereço).","comoBancaPensa":"Rol legal taxativo = terreno para inserir intruso plausível."}},"TI-005":{"cognitivo":{"motivo":"Distinguir trojan, vírus e worm.","mede":"Noções de vírus, worms e pragas virtuais (item 5.2).","pegadinhaDesc":"Atribui ao trojan a característica do WORM (autorreplicação pela rede).","ondeErra":"Confunde as três pragas: vírus (hospedeiro), worm (autorreplica), trojan (disfarce).","palavraCritica":"replica automaticamente = worm (não trojan)","tecnica":"Vírus: precisa de hospedeiro + ação. Worm: autorreplica sozinho na rede. Trojan: se disfarça de programa legítimo.","regraMental":"Trojan = 'presente de grego' (disfarce). Worm = 'verme que se multiplica'. Vírus = 'gruda em arquivo'."},"comentario":{"resolucao":"ERRADO. Quem se replica automaticamente pela rede, sem hospedeiro nem ação do usuário, é o WORM. O cavalo de Troia (trojan) disfarça-se de programa legítimo para induzir a execução e abrir portas/rouba dados, mas não se autorreplica.","fundamento":"Cartilha de Segurança CERT.br — códigos maliciosos.","macete":"Worm = autorreplica. Trojan = disfarce. Vírus = precisa de hospedeiro e do usuário.","erroComum":"Trocar as definições de trojan, worm e vírus.","comoBancaPensa":"Definição perfeita com o nome trocado é o padrão nº 1 de Informática."}},"TI-006":{"cognitivo":{"motivo":"Cobrar o funcionamento da criptografia de chave pública.","mede":"Criptografia e ferramentas (item 4 da Segurança Cibernética).","pegadinhaDesc":"A banca costuma dizer que a mesma chave cifra e decifra (isso é a simétrica).","ondeErra":"Confunde assimétrica (par de chaves) com simétrica (chave única).","palavraCritica":"pública cifra / privada decifra","tecnica":"Simétrica: 1 chave (rápida, problema de distribuição). Assimétrica: 2 chaves (pública + privada).","regraMental":"Sigilo: cifra com a PÚBLICA do destinatário. Autenticidade/assinatura: cifra com a PRIVADA do emissor."},"comentario":{"resolucao":"CERTO. A criptografia assimétrica usa um par matematicamente relacionado (chave pública e chave privada). O que é cifrado por uma só é decifrado pela outra. Para sigilo, cifra-se com a pública do destinatário; para assinatura digital, cifra-se (assina-se) com a privada do emissor.","fundamento":"Fundamentos de segurança da informação — criptografia de chave pública.","macete":"Assimétrica = duas chaves. Simétrica = uma chave só (AES, DES).","erroComum":"Dizer que a mesma chave cifra e decifra (isso é simétrica).","comoBancaPensa":"Simétrica × assimétrica é par conceitual clássico de inversão."}},"TI-007":{"cognitivo":{"motivo":"Distinguir IDS (detecção) de IPS (prevenção) e de firewall.","mede":"Firewalls, IDS/IPS, segmentação de rede (item 3.1).","pegadinhaDesc":"A banca costuma inverter — dizer que o IDS bloqueia e o IPS só alerta.","ondeErra":"Troca o papel detectar × bloquear.","palavraCritica":"IDS = detecta; IPS = previne/bloqueia","tecnica":"IDS = câmera de segurança (alerta). IPS = porta que tranca (bloqueia). Firewall = filtra por regras.","regraMental":"A letra D de IDS = Detecção. A letra P de IPS = Prevenção (bloqueio ativo)."},"comentario":{"resolucao":"CERTO. O IDS monitora e alerta sobre atividades suspeitas (papel passivo/reativo); o IPS, além de detectar, atua ativamente bloqueando o tráfego malicioso. O firewall, por sua vez, filtra o tráfego conforme regras predefinidas.","fundamento":"Segurança de redes — sistemas de detecção e prevenção de intrusão.","macete":"IDS Detecta, IPS Previne. A inicial já entrega a função.","erroComum":"Inverter os papéis de IDS e IPS.","comoBancaPensa":"Siglas de segurança são cobradas trocando a função de cada uma."}},"TI-008":{"cognitivo":{"motivo":"Cobrar os modelos de serviço em nuvem (IaaS, PaaS, SaaS).","mede":"Computação na nuvem (item 3.6 e Segurança em Nuvem).","pegadinhaDesc":"A banca costuma trocar SaaS por IaaS ou atribuir ao SaaS a gestão da infraestrutura.","ondeErra":"Confunde os três modelos e o que cada um entrega ao usuário.","palavraCritica":"aplicação pronta (SaaS)","tecnica":"IaaS = infraestrutura (máquinas). PaaS = plataforma (para desenvolver). SaaS = software pronto (usuário final).","regraMental":"SaaS = 'usa o app' (Gmail). PaaS = 'programa no ambiente'. IaaS = 'aluga o servidor'."},"comentario":{"resolucao":"CERTO. No SaaS, o provedor entrega a aplicação pronta pela Internet (ex.: webmail, suítes online) e o usuário apenas a utiliza, sem responsabilidade sobre infraestrutura, SO ou manutenção. IaaS entrega infraestrutura; PaaS, plataforma de desenvolvimento.","fundamento":"Fundamentos de computação em nuvem (modelos de serviço).","macete":"SaaS = Software pronto; PaaS = Plataforma; IaaS = Infraestrutura.","erroComum":"Atribuir ao SaaS a gestão da infraestrutura (que é do IaaS).","comoBancaPensa":"Os três modelos de nuvem são cobrados trocando o que cada um oferece."}},"TI-009":{"cognitivo":{"motivo":"Cobrar o conceito preciso de MFA (fatores de categorias distintas).","mede":"Autenticação, MFA e SSO (item 6 e Segurança Digital).","pegadinhaDesc":"Começa com a definição correta e emenda a conclusão falsa (duas senhas = MFA).","ondeErra":"Aceita duas senhas (mesmo fator 'conhecimento') como multifator.","palavraCritica":"duas senhas (mesmo fator)","tecnica":"MFA exige fatores de CATEGORIAS diferentes. Duas senhas são o mesmo fator (algo que se sabe).","regraMental":"MFA = combinar categorias: saber (senha) + possuir (token/celular) + ser (biometria)."},"comentario":{"resolucao":"ERRADO. A primeira parte está correta, mas a conclusão é falsa: duas senhas pertencem ao MESMO fator (algo que o usuário sabe), logo não configuram MFA. A autenticação multifator exige combinar fatores de categorias distintas (ex.: senha + código no celular).","fundamento":"Gestão de identidades e acesso — autenticação multifator.","macete":"Multifator ≠ multi-senha. Precisa misturar categorias (saber + ter + ser).","erroComum":"Contar dois fatores do mesmo tipo como MFA.","comoBancaPensa":"Verdade + falso emendado: valida a definição e induz a conclusão errada."}},"TI-010":{"cognitivo":{"motivo":"Distinguir os pilares da tríade CID (Confidencialidade, Integridade, Disponibilidade).","mede":"Princípios de confidencialidade, integridade e disponibilidade (item 1).","pegadinhaDesc":"Descreve a DISPONIBILIDADE e a rotula como integridade.","ondeErra":"Troca os pilares da tríade.","palavraCritica":"acessível/disponível = disponibilidade (não integridade)","tecnica":"Confidencialidade: só quem pode vê. Integridade: não foi alterada indevidamente. Disponibilidade: acessível quando preciso.","regraMental":"CID: Confidencialidade (sigilo), Integridade (exatidão), Disponibilidade (acesso)."},"comentario":{"resolucao":"ERRADO. A descrição (informação acessível quando necessária) corresponde à DISPONIBILIDADE. A integridade garante que a informação não seja alterada de forma indevida ou não autorizada, preservando sua exatidão e completude.","fundamento":"Fundamentos de segurança da informação — tríade CID.","macete":"Integridade = 'não foi adulterada'. Disponibilidade = 'está no ar quando preciso'.","erroComum":"Trocar integridade por disponibilidade.","comoBancaPensa":"A tríade CID é cobrada trocando a definição de um pilar por outro."}},"TI-011":{"cognitivo":{"motivo":"Cobrar o modelo de permissões do Linux.","mede":"Noções de sistema operacional — Linux (item 1 do edital de TI).","pegadinhaDesc":"A banca costuma alterar as categorias (ex.: 'administrador, convidado') ou os tipos de permissão.","ondeErra":"Desconhece o modelo dono/grupo/outros e rwx.","palavraCritica":"dono, grupo, outros / rwx","tecnica":"Linux: 3 categorias (u/g/o) × 3 permissões (r=leitura, w=escrita, x=execução).","regraMental":"Permissões Linux: dono, grupo, outros — cada um com r, w, x (ex.: chmod 755)."},"comentario":{"resolucao":"CERTO. No Linux, cada arquivo/diretório tem permissões para três categorias: dono (user), grupo (group) e outros (others). Cada categoria pode ter leitura (r), escrita (w) e execução (x). Ex.: chmod 755 define rwx para o dono e r-x para grupo e outros.","fundamento":"Sistemas operacionais — Linux (modelo de permissões).","macete":"u/g/o × r/w/x. 'chmod 755' = dono total, grupo e outros só leem e executam.","erroComum":"Trocar as categorias (dono/grupo/outros).","comoBancaPensa":"Modelo de permissões do Linux é cobrado alterando categorias ou tipos."}},"TI-012":{"cognitivo":{"motivo":"Cobrar o conceito de referência absoluta × relativa em planilhas.","mede":"Edição de planilhas — pacote Office (item 2 do edital de TI).","pegadinhaDesc":"A banca costuma dizer que $A$1 é referência relativa ou que muda ao copiar.","ondeErra":"Confunde referência absoluta (fixa) com relativa (ajusta).","palavraCritica":"$ fixa a referência","tecnica":"Sem cifrão = relativa (ajusta ao copiar). Com $ = absoluta (trava). $A1 e A$1 = mistas.","regraMental":"$ = trava. $A$1 não muda; A1 muda ao copiar; $A1 trava a coluna; A$1 trava a linha."},"comentario":{"resolucao":"CERTO. O cifrão ($) fixa a referência: $A$1 é absoluta e não se altera ao copiar a fórmula. Sem cifrão (A1), a referência é relativa e se ajusta. $A1 e A$1 são mistas (travam, respectivamente, a coluna e a linha). Vale para Excel e Calc.","fundamento":"Edição de planilhas (Microsoft Excel / LibreOffice Calc).","macete":"$ trava. $A$1 = fixo total; A$1 = trava linha; $A1 = trava coluna.","erroComum":"Tratar $A$1 como referência relativa.","comoBancaPensa":"Referência absoluta × relativa é o tema clássico de planilhas."}},"TI-013":{"cognitivo":{"motivo":"Cobrar a função da extensão de arquivos.","mede":"Organização e gerenciamento de arquivos (item 4 do edital de TI).","pegadinhaDesc":"A banca costuma dizer que a extensão define o tamanho ou a segurança do arquivo.","ondeErra":"Confunde extensão (tipo/formato) com outros atributos.","palavraCritica":"extensão = tipo/formato","tecnica":"A extensão sinaliza o formato e o programa associado; renomeá-la não converte o conteúdo do arquivo.","regraMental":"Extensão = 'sobrenome' do arquivo: diz o tipo e qual programa abre."},"comentario":{"resolucao":"CERTO. A extensão indica, em regra, o tipo/formato do arquivo e orienta o sistema operacional quanto ao programa associado à sua abertura. Observação: alterar apenas a extensão não converte o conteúdo do arquivo.","fundamento":"Noções de sistema operacional e gerenciamento de arquivos.","macete":"Extensão = tipo do arquivo. Trocar o '.docx' por '.pdf' não vira PDF de verdade.","erroComum":"Achar que a extensão define tamanho ou segurança.","comoBancaPensa":"Conceito básico de arquivos, cobrado de forma direta."}},"TI-014":{"cognitivo":{"motivo":"Cobrar a volatilidade da memória RAM.","mede":"Noções de hardware/sistema operacional (item 1 do edital de TI).","pegadinhaDesc":"Classifica a RAM como não volátil, quando ela é volátil.","ondeErra":"Confunde RAM (volátil) com memória secundária (não volátil, como SSD/HD).","palavraCritica":"não volátil (deveria ser volátil)","tecnica":"RAM: volátil (perde o conteúdo ao desligar). Armazenamento permanente é a memória secundária (HD/SSD/ROM).","regraMental":"RAM = trabalho temporário (volátil). HD/SSD = guarda permanente (não volátil)."},"comentario":{"resolucao":"ERRADO. A memória RAM é VOLÁTIL: seus dados se perdem quando o computador é desligado. A preservação dos dados após o desligamento cabe às memórias não voláteis, como HD, SSD e ROM.","fundamento":"Fundamentos de computação — hierarquia de memórias.","macete":"RAM = volátil (memória de trabalho). Desligou, apagou.","erroComum":"Tratar a RAM como memória permanente.","comoBancaPensa":"Troca a volatilidade da RAM (conceito básico)."}},"TI-015":{"cognitivo":{"motivo":"Cobrar o papel do becape como principal medida de recuperação contra ransomware.","mede":"Procedimentos de backup (item 5.4 do edital de TI).","pegadinhaDesc":"Nega a utilidade do becape justamente no cenário em que ele é decisivo.","ondeErra":"Confunde prevenção da infecção com recuperação dos dados.","palavraCritica":"irrelevante (falso)","tecnica":"O becape não impede o ataque, mas permite RESTAURAR os dados sem pagar resgate — é a principal medida de continuidade.","regraMental":"Contra ransomware, becape íntegro e isolado é a melhor defesa: restaura sem pagar."},"comentario":{"resolucao":"ERRADO. O becape é justamente a principal medida de mitigação contra ransomware: permite restaurar os dados sem ceder à extorsão. Recomenda-se que as cópias sejam íntegras, testadas e mantidas isoladas da rede (offline), para que não sejam também cifradas.","fundamento":"Segurança da informação — procedimentos de becape e continuidade.","macete":"Becape isolado e testado = você restaura e não paga resgate.","erroComum":"Achar que o becape só serve para prevenir a infecção.","comoBancaPensa":"Nega a utilidade de uma medida no cenário em que ela é essencial."}},"TI-016":{"cognitivo":{"motivo":"Cobrar que o incidente não afasta a incidência da LGPD, mas gera deveres adicionais.","mede":"LGPD (item 7 do edital de TI).","pegadinhaDesc":"Cria uma causa de exclusão da LGPD inexistente.","ondeErra":"Supõe que ser vítima de ataque isenta o controlador de obrigações.","palavraCritica":"deixam de se submeter (falso)","tecnica":"O incidente ATIVA deveres: comunicar à ANPD e aos titulares, adotar medidas de segurança e mitigar efeitos.","regraMental":"Sofrer ataque não isenta: a LGPD continua e ainda impõe comunicar o incidente."},"comentario":{"resolucao":"ERRADO. O incidente de segurança não afasta a aplicação da LGPD — ao contrário, faz incidir deveres específicos: o controlador deve comunicar à ANPD e aos titulares a ocorrência que possa acarretar risco ou dano relevante (art. 48) e responde por não adotar medidas de segurança adequadas (arts. 46 a 50).","fundamento":"Lei 13.709/2018, arts. 46 a 50.","macete":"Vazou? Comunica ANPD e titulares. A responsabilidade do controlador permanece.","erroComum":"Supor que o ataque transfere toda a responsabilidade ao criminoso.","comoBancaPensa":"Inventa hipótese de exclusão da LGPD."}},"TI-017":{"cognitivo":{"motivo":"Cobrar as funções centrais do NIST CSF.","mede":"TI/Segurança — frameworks de segurança da informação.","pegadinhaDesc":"A banca omite a função 'recuperar', dando a entender que o framework para em 'responder'.","ondeErra":"Não memoriza as cinco funções centrais do framework e aceita a omissão da última.","palavraCritica":"prescindindo de ... recuperação","tecnica":"NIST CSF: 5 funções centrais — Identify (identificar), Protect (proteger), Detect (detectar), Respond (responder), Recover (recuperar). A função Recover é parte essencial do framework, não dispensável.","regraMental":"NIST CSF: IPDRR — Identificar, Proteger, Detectar, Responder, Recuperar."},"comentario":{"resolucao":"ERRADO. O NIST Cybersecurity Framework inclui, sim, uma quinta função essencial: Recuperar (Recover), além de Identificar, Proteger, Detectar e Responder (IPDRR). O framework não prescinde dessa função — ela orienta o retorno à normalidade após o incidente.","fundamento":"TI/Segurança — NIST Cybersecurity Framework (NIST CSF).","macete":"IPDRR: Identificar, Proteger, Detectar, Responder, Recuperar.","erroComum":"Omitir a função 'Recuperar' ao listar as funções do framework.","comoBancaPensa":"Omite uma das cinco funções para testar a memorização completa."}},"TI-018":{"cognitivo":{"motivo":"Cobrar o conceito de SSO.","mede":"TI/Segurança — gestão de identidades e acesso.","pegadinhaDesc":"A banca pode confundir SSO com MFA ou exigir múltiplas autenticações.","ondeErra":"Acha que o SSO exige nova autenticação em cada sistema.","palavraCritica":"única autenticação ... múltiplos sistemas","tecnica":"SSO: uma única autenticação dá acesso a vários sistemas integrados, sem repetir login em cada um. Frequentemente implementado com protocolos como SAML, OAuth2 ou OpenID Connect.","regraMental":"SSO: logou uma vez, acessa tudo (sem repetir senha em cada sistema)."},"comentario":{"resolucao":"CERTO. O Single Sign-On (SSO) permite que, mediante uma única autenticação inicial, o usuário tenha acesso a múltiplos sistemas ou aplicações integradas, sem necessidade de nova inserção de credenciais a cada acesso — geralmente implementado com protocolos como SAML, OAuth2 ou OpenID Connect.","fundamento":"TI/Segurança — gestão de identidades e acesso (SSO).","macete":"SSO: um login só, acesso a vários sistemas.","erroComum":"Exigir reautenticação em cada sistema, negando a essência do SSO.","comoBancaPensa":"Item de fixação conceitual sobre gestão de acesso."}},"TI-019":{"cognitivo":{"motivo":"Cobrar a distinção entre criptografia simétrica e assimétrica.","mede":"TI/Segurança — criptografia.","pegadinhaDesc":"A banca inverte os conceitos de simétrica e assimétrica.","ondeErra":"Aceita a troca sem perceber a inversão dos nomes.","palavraCritica":"mesma chave ... par de chaves distintas","tecnica":"Simétrica: 1 chave (cifra e decifra). Assimétrica: par de chaves (pública/privada) — uma cifra, a outra decifra. O enunciado trocou os dois nomes entre si.","regraMental":"Simétrica: 1 chave para tudo. Assimétrica: par de chaves (pública + privada)."},"comentario":{"resolucao":"ERRADO. Os conceitos foram invertidos. Na criptografia simétrica (e não assimétrica) a mesma chave cifra e decifra a informação. Na criptografia assimétrica (e não simétrica) utiliza-se um par de chaves — pública e privada —, de modo que uma cifra e a outra decifra.","fundamento":"TI/Segurança — técnicas de criptografia.","macete":"Simétrica: 1 chave. Assimétrica: par de chaves (pública/privada).","erroComum":"Não perceber a inversão entre simétrica e assimétrica.","comoBancaPensa":"Item de fixação conceitual clássico de criptografia, com troca dos rótulos."}},"TI-020":{"cognitivo":{"motivo":"Cobrar a regra 3-2-1 de backup.","mede":"TI/Segurança — procedimentos de backup.","pegadinhaDesc":"A banca troca os números da regra (3 cópias/2 mídias vira 2 cópias/3 mídias).","ondeErra":"Não retém os três números da regra (3, 2, 1) e aceita a troca.","palavraCritica":"duas cópias ... três tipos de mídia","tecnica":"Regra 3-2-1: 3 cópias dos dados, em 2 mídias diferentes, com 1 cópia off-site (fora do local) — e não 2 cópias em 3 mídias.","regraMental":"3 cópias, 2 mídias, 1 fora do local."},"comentario":{"resolucao":"ERRADO. Os números foram trocados. A regra correta é: 3 cópias dos dados (e não 2), armazenadas em 2 tipos diferentes de mídia (e não 3), com pelo menos 1 cópia mantida em local externo (off-site).","fundamento":"TI/Segurança — boas práticas de backup (regra 3-2-1).","macete":"3 cópias, 2 mídias, 1 fora do local.","erroComum":"Trocar os números da regra.","comoBancaPensa":"Troca os números corretos por outros plausíveis."}},"TI-021":{"cognitivo":{"motivo":"Cobrar a distinção entre IDS (passivo) e IPS (ativo).","mede":"TI/Segurança — segurança de rede.","pegadinhaDesc":"A banca inverte as funções, atribuindo o papel passivo ao IPS e o ativo ao IDS.","ondeErra":"Aceita a troca sem perceber a inversão entre IDS e IPS.","palavraCritica":"detectar e alertar ... bloquear","tecnica":"IDS: monitora e ALERTA (passivo). IPS: monitora e BLOQUEIA automaticamente (ativo, geralmente em linha com o tráfego). O enunciado trocou os dois nomes entre si.","regraMental":"IDS: só avisa. IPS: além de avisar, também age/bloqueia."},"comentario":{"resolucao":"ERRADO. Os papéis foram invertidos. O IDS (e não o IPS) atua de forma passiva, detectando e alertando sobre atividades suspeitas sem bloqueá-las. Já o IPS (e não o IDS) atua de forma ativa, podendo bloquear automaticamente o tráfego identificado como malicioso.","fundamento":"TI/Segurança — segurança de rede (IDS/IPS).","macete":"IDS: detecta e alerta (passivo). IPS: detecta e bloqueia (ativo).","erroComum":"Não perceber a troca de nomes entre IDS e IPS.","comoBancaPensa":"Item de fixação conceitual sobre soluções de segurança de rede, com inversão dos rótulos."}},"TI-022":{"cognitivo":{"motivo":"Cobrar o modelo de responsabilidade compartilhada em nuvem.","mede":"TI/Segurança — segurança em nuvem.","pegadinhaDesc":"A banca pode atribuir toda a responsabilidade só ao provedor ou só ao cliente.","ondeErra":"Acha que o provedor de nuvem é responsável por tudo, inclusive a configuração do cliente.","palavraCritica":"provedor ... infraestrutura. Cliente ... configuração e dados","tecnica":"Modelo de responsabilidade compartilhada: o provedor cuida da segurança 'DA nuvem' (infraestrutura física, hardware, virtualização); o cliente cuida da segurança 'NA nuvem' (configurações de acesso, dados, aplicações).","regraMental":"Segurança DA nuvem = provedor. Segurança NA nuvem = cliente."},"comentario":{"resolucao":"CERTO. No modelo de responsabilidade compartilhada, o provedor de nuvem responde pela segurança da infraestrutura física subjacente (segurança 'da' nuvem), enquanto o cliente é responsável pela segurança das configurações de acesso, dos dados e das aplicações que utiliza (segurança 'na' nuvem).","fundamento":"TI/Segurança — práticas de segurança em ambientes de nuvem.","macete":"Segurança DA nuvem: provedor. Segurança NA nuvem: cliente.","erroComum":"Atribuir toda a responsabilidade a uma única parte.","comoBancaPensa":"Testa a divisão correta de responsabilidades no modelo de nuvem."}},"TI-023":{"cognitivo":{"motivo":"Cobrar a tríade CID (fundamentos de segurança).","mede":"TI/Segurança — fundamentos de segurança da informação.","pegadinhaDesc":"A banca pode trocar os conceitos entre si (ex.: integridade = acesso restrito).","ondeErra":"Confunde confidencialidade (quem acessa) com integridade (dado correto).","palavraCritica":"confidencialidade ... integridade ... disponibilidade","tecnica":"Tríade CID: Confidencialidade (só quem é autorizado acessa), Integridade (dado correto/não alterado indevidamente), Disponibilidade (acesso quando necessário).","regraMental":"CID: Confidencial (quem vê), Íntegro (dado certo), Disponível (quando precisar)."},"comentario":{"resolucao":"CERTO. A tríade CID resume os fundamentos da segurança da informação: confidencialidade (acesso restrito a pessoas autorizadas), integridade (exatidão dos dados, sem alteração indevida) e disponibilidade (acesso garantido sempre que necessário aos usuários autorizados).","fundamento":"TI/Segurança — fundamentos de segurança da informação (tríade CID).","macete":"CID: Confidencialidade, Integridade, Disponibilidade.","erroComum":"Trocar os significados dos três princípios entre si.","comoBancaPensa":"Item de fixação (nível fácil) sobre os fundamentos da segurança."}},"TI-024":{"cognitivo":{"motivo":"Cobrar a real função do comando chmod, distinta do comando chown.","mede":"TI/Segurança — sistemas operacionais Linux (permissões).","pegadinhaDesc":"A banca troca a função do chmod (permissões) pela do chown (proprietário).","ondeErra":"Confunde os dois comandos clássicos de administração de arquivos no Linux.","palavraCritica":"exclusivamente ... proprietário","tecnica":"O comando CHMOD ('change mode') altera as permissões de leitura (r), escrita (w) e execução (x) de um arquivo ou diretório para proprietário, grupo e outros. Quem altera o PROPRIETÁRIO é o comando CHOWN ('change owner') — são comandos distintos.","regraMental":"chmod = permissões (rwx). chown = dono do arquivo."},"comentario":{"resolucao":"ERRADO. O comando chmod é utilizado exatamente para alterar as permissões de leitura, escrita e execução de um arquivo ou diretório — quem altera o proprietário é o comando chown, e não o chmod.","fundamento":"Sistemas operacionais Linux — administração de permissões de arquivos.","macete":"chmod = permissões. chown = proprietário. Não confunda os dois comandos.","erroComum":"Trocar a função dos dois comandos entre si.","comoBancaPensa":"Item clássico de fixação sobre comandos básicos de administração Linux."}},"TI-025":{"cognitivo":{"motivo":"Cobrar a função correta do comando chmod.","mede":"TI/Segurança — sistemas operacionais Linux (permissões).","pegadinhaDesc":"A banca pode restringir a aplicação apenas ao proprietário, ignorando grupo e outros usuários.","ondeErra":"Esquece que o chmod também altera permissões para grupo e para os demais usuários ('outros').","palavraCritica":"proprietário, o grupo e os demais usuários","tecnica":"O comando chmod altera as permissões de leitura (r), escrita (w) e execução (x) de um arquivo ou diretório, aplicáveis separadamente a três categorias: proprietário (user), grupo (group) e outros usuários (others).","regraMental":"chmod: três categorias (user, group, others) × três permissões (r, w, x)."},"comentario":{"resolucao":"CERTO. O comando chmod altera as permissões de leitura, escrita e execução de um arquivo ou diretório, podendo ser aplicadas separadamente às três categorias de usuários: proprietário, grupo e demais usuários.","fundamento":"Sistemas operacionais Linux — administração de permissões de arquivos.","macete":"chmod: 3 categorias (dono, grupo, outros) × 3 permissões (ler, escrever, executar).","erroComum":"Restringir a aplicação do chmod apenas ao proprietário do arquivo.","comoBancaPensa":"Item de fixação sobre a abrangência completa do comando."}},"TI-026":{"cognitivo":{"motivo":"Cobrar a real finalidade do modelo conceitual, distinta do modelo físico.","mede":"TI/Segurança — banco de dados (modelagem).","pegadinhaDesc":"A banca atribui ao modelo conceitual (DER) uma finalidade típica do modelo físico.","ondeErra":"Confunde o nível conceitual (entidades, atributos, relacionamentos) com o nível físico (índices, arquivos, parâmetros do SGBD).","palavraCritica":"estrutura física de armazenamento","tecnica":"O modelo CONCEITUAL (DER) descreve entidades, atributos e relacionamentos de forma abstrata, independente de tecnologia — é quem descreve a estrutura FÍSICA (índices, tipos de arquivo, parâmetros do SGBD) é o modelo FÍSICO, etapa posterior da modelagem.","regraMental":"DER/conceitual: entidades e relacionamentos (abstrato). Modelo físico: índices e armazenamento real (SGBD específico)."},"comentario":{"resolucao":"ERRADO. O modelo conceitual, representado pelo DER, descreve entidades, atributos e relacionamentos de forma abstrata e independente de tecnologia — quem descreve a estrutura física de armazenamento (índices, tipos de arquivo, parâmetros do SGBD) é o modelo FÍSICO, e não o conceitual.","fundamento":"Modelagem de dados — modelo conceitual, lógico e físico.","macete":"Conceitual (DER) = abstrato, sem tecnologia. Físico = índices e SGBD específico.","erroComum":"Atribuir ao modelo conceitual características que só existem no modelo físico.","comoBancaPensa":"Troca as finalidades de dois níveis distintos de modelagem de dados."}},"TI-027":{"cognitivo":{"motivo":"Cobrar a real finalidade do modelo conceitual (DER).","mede":"TI/Segurança — banco de dados (modelagem).","pegadinhaDesc":"A banca pode negar essa abstração, exigindo detalhes de implementação já no modelo conceitual.","ondeErra":"Não distingue os três níveis de modelagem: conceitual, lógico e físico.","palavraCritica":"sem se preocupar com ... implementação física","tecnica":"O modelo conceitual (DER) é o nível mais abstrato de modelagem: descreve entidades, atributos e relacionamentos relevantes ao negócio, sem qualquer preocupação com o SGBD específico ou com detalhes de armazenamento físico — esses detalhes só aparecem no modelo lógico (parcialmente) e no modelo físico (integralmente).","regraMental":"Conceitual → lógico → físico: do mais abstrato ao mais concreto/tecnológico."},"comentario":{"resolucao":"CERTO. O modelo conceitual, representado pelo DER, é o nível mais abstrato de modelagem de dados, descrevendo entidades, atributos e relacionamentos relevantes ao negócio, sem qualquer preocupação com detalhes de implementação física ou com o SGBD específico a ser utilizado.","fundamento":"Modelagem de dados — modelo conceitual, lógico e físico.","macete":"DER/conceitual: só o 'o quê' do negócio, nunca o 'como' tecnológico.","erroComum":"Exigir detalhes de implementação já no nível conceitual da modelagem.","comoBancaPensa":"Item de fixação sobre a real abstração do modelo conceitual."}},"TI-028":{"cognitivo":{"motivo":"Cobrar a classificação correta dos comandos básicos de manipulação de dados em SQL.","mede":"TI/Segurança — linguagem SQL (categorias de comandos).","pegadinhaDesc":"A banca pode classificar esses comandos como DDL (Data Definition Language).","ondeErra":"Confunde DML (manipulação de dados) com DDL (definição de estruturas, como CREATE, ALTER, DROP).","palavraCritica":"DML","tecnica":"SELECT, INSERT, UPDATE e DELETE são comandos de DML (Data Manipulation Language) — usados para consultar e manipular os dados já armazenados. DDL (CREATE, ALTER, DROP) define a estrutura das tabelas; DCL (GRANT, REVOKE) controla permissões de acesso.","regraMental":"DML: SELECT/INSERT/UPDATE/DELETE (dados). DDL: CREATE/ALTER/DROP (estrutura). DCL: GRANT/REVOKE (permissões)."},"comentario":{"resolucao":"CERTO. Os comandos SELECT, INSERT, UPDATE e DELETE pertencem à categoria DML (Data Manipulation Language) da linguagem SQL, empregados para consultar e manipular os dados armazenados nas tabelas de um banco de dados relacional.","fundamento":"Linguagem SQL — categorias de comandos (DML, DDL, DCL).","macete":"DML = SELECT/INSERT/UPDATE/DELETE. DDL = CREATE/ALTER/DROP. DCL = GRANT/REVOKE.","erroComum":"Confundir DML com DDL ou DCL.","comoBancaPensa":"Item de fixação sobre a classificação básica dos comandos SQL."}},"TI-029":{"cognitivo":{"motivo":"Cobrar que o DDoS compromete a disponibilidade, e não a confidencialidade, da tríade CID.","mede":"TI/Segurança — fundamentos de segurança (tríade CID).","pegadinhaDesc":"A banca troca o princípio comprometido pelo ataque DDoS (disponibilidade) por outro (confidencialidade).","ondeErra":"Confunde 'impedir o acesso' com 'quebra de confidencialidade' (que trata de acesso indevido por quem NÃO deveria acessar, não de indisponibilidade para quem deveria).","palavraCritica":"confidencialidade","tecnica":"Na tríade CID: Confidencialidade é violada quando pessoas NÃO autorizadas acessam a informação. Disponibilidade é violada quando usuários AUTORIZADOS ficam impedidos de acessar. O DDoS, ao tornar o sistema indisponível, compromete a DISPONIBILIDADE, não a confidencialidade.","regraMental":"DDoS = ataque de DISPONIBILIDADE (impede acesso de quem deveria acessar), não de confidencialidade."},"comentario":{"resolucao":"ERRADO. O ataque DDoS compromete o princípio da DISPONIBILIDADE (e não da confidencialidade), pois impede que usuários legítimos e autorizados acessem o sistema ou os dados — a confidencialidade seria violada apenas se pessoas não autorizadas obtivessem acesso indevido às informações.","fundamento":"Segurança da informação — tríade CID (confidencialidade, integridade, disponibilidade).","macete":"DDoS ataca a DISPONIBILIDADE. Confidencialidade é sobre acesso indevido, não indisponibilidade.","erroComum":"Confundir 'impedir acesso de usuários legítimos' com 'violação de confidencialidade'.","comoBancaPensa":"Troca o princípio correto da tríade CID por outro, testando a precisão conceitual do candidato."}},"TI-030":{"cognitivo":{"motivo":"Cobrar o conceito correto de risco residual, posterior aos controles.","mede":"TI/Segurança — gestão de riscos em segurança da informação.","pegadinhaDesc":"A banca pode inverter o momento (risco residual seria antes dos controles) ou afirmar que ele é totalmente eliminado.","ondeErra":"Confunde risco residual (após os controles) com risco inerente (antes dos controles).","palavraCritica":"após a aplicação dos controles ... não sendo eliminado por completo","tecnica":"Risco RESIDUAL é o risco que PERMANECE após a aplicação de controles de segurança — nenhum controle elimina 100% do risco. Risco INERENTE (ou risco bruto) é o nível de risco ANTES da aplicação de qualquer controle.","regraMental":"Risco inerente = antes dos controles. Risco residual = depois dos controles, e nunca é zero."},"comentario":{"resolucao":"CERTO. O risco residual é o nível de risco que permanece após a implementação de controles de segurança — nenhum conjunto de controles elimina totalmente o risco, restando sempre um resíduo a ser gerenciado (aceito, monitorado ou mitigado ainda mais).","fundamento":"Gestão de riscos em segurança da informação (ISO 27005; doutrina de governança de TI).","macete":"Risco residual = depois dos controles, nunca zero. Risco inerente = antes dos controles.","erroComum":"Confundir risco residual com risco inerente (antes dos controles).","comoBancaPensa":"Item de fixação sobre um conceito central da gestão de riscos em segurança da informação."}},"TI-031":{"cognitivo":{"motivo":"Cobrar a imutabilidade da classe String em Java.","mede":"TI/Segurança — linguagem de programação Java.","pegadinhaDesc":"A banca afirma que a String é mutável, quando na verdade é uma das classes imutáveis mais conhecidas do Java.","ondeErra":"Confunde StringBuilder/StringBuffer (mutáveis) com String (imutável).","palavraCritica":"estrutura mutável ... sem a criação de um novo objeto","tecnica":"Em Java, String é IMUTÁVEL: qualquer operação como concat() ou replace() NÃO altera o objeto original — ela cria e retorna um NOVO objeto String em memória, mantendo o original inalterado. Quem permite alteração direta (mutabilidade) são as classes StringBuilder e StringBuffer.","regraMental":"String em Java: sempre imutável. concat()/replace() criam objeto novo, não alteram o original."},"comentario":{"resolucao":"ERRADO. A classe String em Java é IMUTÁVEL — métodos como concat() e replace() não alteram o objeto original, mas retornam um NOVO objeto String em memória. A mutabilidade direta é característica de StringBuilder e StringBuffer, não de String.","fundamento":"Linguagem de programação Java — estruturas de dados (imutabilidade da String).","macete":"String = imutável (sempre cria novo objeto). StringBuilder/StringBuffer = mutáveis.","erroComum":"Confundir a imutabilidade da String com a mutabilidade do StringBuilder/StringBuffer.","comoBancaPensa":"Inverte uma característica fundamental e bem conhecida da linguagem Java."}},"TI-032":{"cognitivo":{"motivo":"Cobrar a distinção correta entre autorização (OAuth2) e autenticação (OpenID Connect).","mede":"TI/Segurança — gestão de identidades e acesso.","pegadinhaDesc":"A banca pode inverter as finalidades ou classificar o OpenID Connect como protocolo obsoleto.","ondeErra":"Confunde autorização (conceder acesso a recursos) com autenticação (verificar identidade).","palavraCritica":"autorizar ... camada de autenticação","tecnica":"OAuth2 é um protocolo de AUTORIZAÇÃO: permite que uma aplicação acesse recursos em nome do usuário, sem necessariamente confirmar quem é esse usuário. O OpenID Connect é uma camada de AUTENTICAÇÃO construída sobre o OAuth2, adicionando a verificação padronizada da identidade — é tecnologia atual e amplamente utilizada, não obsoleta.","regraMental":"OAuth2 = autorização (acesso a recursos). OpenID Connect = autenticação (confirma identidade), sobre o OAuth2."},"comentario":{"resolucao":"CERTO. O OAuth2 é protocolo de autorização, voltado a conceder acesso de aplicações a recursos do usuário sem necessariamente autenticar sua identidade. O OpenID Connect é uma camada de autenticação construída sobre o OAuth2, permitindo verificar a identidade do usuário de forma padronizada — tecnologia atual, não obsoleta.","fundamento":"TI/Segurança — protocolos de autenticação e autorização (OAuth2, OpenID Connect).","macete":"OAuth2 = autorização. OpenID Connect = autenticação (construído sobre o OAuth2).","erroComum":"Achar que o OAuth2 já autentica a identidade do usuário por si só, ou que o OpenID Connect é obsoleto.","comoBancaPensa":"Item de fixação sobre a distinção fina entre dois protocolos frequentemente confundidos."}},"TI-033":{"cognitivo":{"motivo":"Cobrar que SIEM e PAM têm funções distintas e complementares, não substituíveis entre si.","mede":"TI/Segurança — soluções de segurança da informação (SIEM, PAM).","pegadinhaDesc":"A banca atribui ao SIEM a função que é, na verdade, do PAM.","ondeErra":"Confunde a função de monitoramento e correlação de eventos (SIEM) com a de gestão de acessos privilegiados (PAM).","palavraCritica":"gerenciar identidades e privilégios ... substituindo","tecnica":"SIEM (Security Information and Event Management) coleta, correlaciona e monitora eventos e logs de segurança de toda a organização, gerando alertas. PAM (Privileged Access Management) é quem gerencia especificamente as identidades e os privilégios de acesso de usuários privilegiados (administradores). São soluções complementares, não substitutas uma da outra.","regraMental":"SIEM = monitora e correlaciona eventos/logs. PAM = gerencia acessos privilegiados. Não se substituem."},"comentario":{"resolucao":"ERRADO. O SIEM tem como função principal coletar, correlacionar e monitorar eventos e logs de segurança de toda a organização, gerando alertas — quem gerencia especificamente as identidades e os privilégios de acesso de usuários privilegiados é o PAM. São soluções complementares, e o SIEM não substitui a necessidade de um PAM.","fundamento":"TI/Segurança — soluções de segurança da informação (SIEM e PAM).","macete":"SIEM = monitora eventos/logs. PAM = gerencia acessos privilegiados. São complementares.","erroComum":"Achar que uma solução de monitoramento de eventos (SIEM) substitui a gestão de acessos privilegiados (PAM).","comoBancaPensa":"Atribui a uma solução a função de outra, testando se o candidato conhece a finalidade específica de cada ferramenta."}},"TI-034":{"cognitivo":{"motivo":"Cobrar a característica central e definidora do worm: autopropagação automática pela rede.","mede":"Segurança da Informação — malwares (worm).","pegadinhaDesc":"A banca pode negar a autopropagação automática ou exigir um hospedeiro/mídia removível.","ondeErra":"Confunde o worm com o vírus (que depende de hospedeiro) ou presume que toda praga precisa de ação do usuário.","palavraCritica":"sem depender de um arquivo hospedeiro","tecnica":"O worm se propaga SOZINHO pela rede, explorando falhas de segurança de software, sem precisar de um arquivo hospedeiro (diferença central para o vírus) nem de mídia removível.","regraMental":"Worm = autopropagação automática pela rede, sem hospedeiro."},"comentario":{"resolucao":"CERTO. O worm é definido justamente pela capacidade de se replicar e se propagar automaticamente pela rede, de computador para computador, explorando vulnerabilidades de segurança — sem depender de um arquivo hospedeiro (como o vírus) nem de ação humana para se disseminar.","fundamento":"Doutrina de segurança da informação — taxonomia de malwares (worm).","macete":"Worm se vira sozinho: rede + vulnerabilidade = propagação automática.","erroComum":"Confundir com vírus (hospedeiro) ou trojan (ação do usuário).","comoBancaPensa":"Item 'limpo', sem cruzamento de conceitos — quando a definição bate exatamente com a característica certa, tende a estar correto."}},"TI-035":{"cognitivo":{"motivo":"Cobrar, na forma invertida, a autopropagação automática do worm.","mede":"Segurança da Informação — malwares (worm).","pegadinhaDesc":"A banca nega a autopropagação em rede e atribui ao worm uma dependência que não é sua.","ondeErra":"Aceita a inversão sem perceber que é exatamente o worm quem dispensa mídia removível.","palavraCritica":"incapaz","tecnica":"O worm se propaga automaticamente pela rede (e-mail, falhas de segurança, compartilhamentos), sem qualquer necessidade de mídia removível — a palavra 'incapaz' já denuncia a inversão.","regraMental":"Termos absolutos como 'incapaz' e 'sempre' costumam sinalizar item errado."},"comentario":{"resolucao":"ERRADO. O worm é justamente capaz de se propagar automaticamente pelas redes, sem depender de mídia removível — essa dependência de meio físico externo é característica mais próxima do vírus clássico, não do worm.","fundamento":"Doutrina de segurança da informação — taxonomia de malwares (worm).","macete":"Palavra absoluta ('incapaz') + característica invertida = pegadinha clássica.","erroComum":"Inverter a definição de worm com a de vírus.","comoBancaPensa":"Nega a característica definidora do malware e atribui a ele uma limitação inexistente."}},"TI-036":{"cognitivo":{"motivo":"Cobrar a distinção clássica entre vírus (dependente de hospedeiro) e worm (autônomo).","mede":"Segurança da Informação — malwares (vírus x worm).","pegadinhaDesc":"A banca pode inverter, atribuindo ao vírus a autopropagação do worm.","ondeErra":"Troca as características de vírus e worm entre si.","palavraCritica":"depende de um arquivo ou programa hospedeiro","tecnica":"O vírus precisa se anexar a um arquivo/programa hospedeiro para se replicar e depende, em regra, da execução desse hospedeiro pelo usuário — diferentemente do worm, que se propaga sozinho pela rede.","regraMental":"Vírus = precisa de hospedeiro. Worm = autônomo, explora a rede."},"comentario":{"resolucao":"CERTO. O vírus de computador é definido pela dependência de um arquivo ou programa hospedeiro para se replicar e se disseminar — ao contrário do worm, que se autopropaga pela rede de forma independente, explorando vulnerabilidades de segurança.","fundamento":"Doutrina de segurança da informação — taxonomia de malwares (vírus x worm).","macete":"Vírus precisa de 'carona' (hospedeiro); worm anda sozinho.","erroComum":"Inverter as definições de vírus e worm.","comoBancaPensa":"Cobra a distinção mais clássica e recorrente da taxonomia de malwares."}},"TI-037":{"cognitivo":{"motivo":"Cobrar que o trojan NÃO se autopropaga pela rede (comportamento típico do worm).","mede":"Segurança da Informação — malwares (trojan).","pegadinhaDesc":"A banca atribui ao trojan o comportamento de autopropagação em rede, que é do worm.","ondeErra":"Confunde o trojan (depende da ação do usuário) com o worm (autopropagação automática).","palavraCritica":"propaga-se automaticamente pela rede","tecnica":"O trojan se disfarça de programa legítimo e depende da própria vítima para ser instalado/executado — ele não se autorreplica nem se propaga sozinho pela rede infectando outros dispositivos, ao contrário do worm.","regraMental":"Quem se autopropaga pela rede é o worm. O trojan depende do usuário instalar."},"comentario":{"resolucao":"ERRADO. Autopropagar-se pela rede, enviando cópias de si mesmo e infectando outros dispositivos, é comportamento típico do worm, e não do trojan — este último depende da ação do próprio usuário, que o instala acreditando se tratar de um programa legítimo.","fundamento":"Doutrina de segurança da informação — taxonomia de malwares (trojan x worm).","macete":"Trojan não anda sozinho pela rede — quem faz isso é o worm.","erroComum":"Atribuir ao trojan o comportamento de autopropagação que é próprio do worm.","comoBancaPensa":"Cruza dois malwares distintos na mesma frase, dando a um a característica do outro."}},"TI-038":{"cognitivo":{"motivo":"Cobrar a característica correta do trojan: disfarce + instalação pelo próprio usuário.","mede":"Segurança da Informação — malwares (trojan).","pegadinhaDesc":"A banca pode negar o disfarce ou atribuir autopropagação ao trojan.","ondeErra":"Confunde trojan com worm quanto à forma de disseminação.","palavraCritica":"não possuindo capacidade de se autopropagar","tecnica":"O trojan se disfarça de software legítimo/útil para enganar a vítima, que o instala por conta própria — ele pode transportar outros malwares, mas não se autorreplica nem se propaga sozinho pela rede.","regraMental":"Trojan engana e é instalado pelo usuário; worm se propaga sozinho."},"comentario":{"resolucao":"CERTO. O trojan se caracteriza pelo disfarce de programa legítimo, contando com a própria ação do usuário para ser instalado — diferentemente do worm, ele não possui capacidade de autopropagação automática pela rede.","fundamento":"Doutrina de segurança da informação — taxonomia de malwares (trojan).","macete":"Trojan = engano + instalação voluntária da vítima.","erroComum":"Atribuir ao trojan a autopropagação típica do worm.","comoBancaPensa":"Item de fixação sobre a característica central e correta do trojan."}},"TI-039":{"cognitivo":{"motivo":"Cobrar a definição correta do ransomware (criptografia + resgate), distinta da do spyware.","mede":"Segurança da Informação — malwares (ransomware).","pegadinhaDesc":"A banca atribui ao ransomware a função de captura de dados/spam, que é do spyware/adware.","ondeErra":"Confunde ransomware (sequestro de dados mediante criptografia) com spyware (coleta de dados).","palavraCritica":"capturar dados pessoais ... enviar spam","tecnica":"A característica central do ransomware é bloquear o acesso ou criptografar os dados da vítima e exigir pagamento de resgate — capturar dados pessoais para envio de spam é comportamento típico de spyware/adware, não de ransomware.","regraMental":"Ransomware = criptografia + resgate. Captura de dados para spam = spyware/adware."},"comentario":{"resolucao":"ERRADO. O ransomware tem como característica definidora bloquear o acesso a um sistema ou criptografar os dados da vítima, exigindo pagamento de resgate para restabelecer o acesso — capturar dados pessoais para envio de spam sem autorização é comportamento típico do spyware/adware, e não do ransomware.","fundamento":"Doutrina de segurança da informação — taxonomia de malwares (ransomware x spyware).","macete":"Ransomware é resgate, não roubo de dados para spam.","erroComum":"Misturar as características de ransomware e spyware na mesma definição.","comoBancaPensa":"Cruza dois malwares distintos na mesma frase — padrão clássico de item errado."}},"TI-040":{"cognitivo":{"motivo":"Cobrar que o firewall controla tráfego de rede, e não escaneia arquivos (função do antivírus).","mede":"Segurança da Informação — firewall x antivírus.","pegadinhaDesc":"A banca atribui ao firewall a função de escanear arquivos, que é do antivírus.","ondeErra":"Confunde controle de tráfego de rede (firewall) com varredura de arquivos armazenados (antivírus).","palavraCritica":"verificação de seus arquivos","tecnica":"O firewall é uma barreira que controla o tráfego de entrada e saída de uma rede, com base em regras predefinidas — ele não realiza varredura de arquivos armazenados em busca de malware; essa é a função do antivírus.","regraMental":"Firewall = tráfego de rede. Antivírus = arquivos armazenados."},"comentario":{"resolucao":"ERRADO. O firewall controla o tráfego de dados que entra e sai de uma rede, com base em regras de filtragem — quem realiza a verificação de arquivos armazenados em busca de códigos maliciosos é o antivírus, e não o firewall.","fundamento":"Doutrina de segurança da informação — ferramentas de proteção (firewall x antivírus).","macete":"Firewall cuida do tráfego; antivírus cuida dos arquivos.","erroComum":"Atribuir ao firewall a função de escaneamento de arquivos do antivírus.","comoBancaPensa":"Erro clássico: atribuir a uma ferramenta de segurança a função de outra."}},"TI-041":{"cognitivo":{"motivo":"Cobrar a definição correta e completa do firewall.","mede":"Segurança da Informação — firewall.","pegadinhaDesc":"A banca pode restringir o firewall a apenas hardware ou apenas software.","ondeErra":"Não reconhece que o firewall pode ser implementado em hardware, software ou de forma combinada.","palavraCritica":"hardware, em software ou em ambos","tecnica":"O firewall é um mecanismo (físico, lógico ou híbrido) que filtra o tráfego de rede de entrada e saída, permitindo ou bloqueando pacotes de dados conforme regras de segurança predefinidas.","regraMental":"Firewall: pode ser hardware, software ou os dois — sempre controlando tráfego por regras."},"comentario":{"resolucao":"CERTO. O firewall pode ser implementado em hardware, em software ou em uma combinação de ambos, exercendo a função de controlar o tráfego de dados de entrada e saída de uma rede, permitindo ou bloqueando conexões conforme regras de segurança predefinidas.","fundamento":"Doutrina de segurança da informação — mecanismos de proteção de rede (firewall).","macete":"Firewall: hardware, software, ou os dois — sempre regras de tráfego.","erroComum":"Restringir o firewall a apenas uma das formas de implementação.","comoBancaPensa":"Item de fixação sobre a definição completa e correta do firewall."}},"TI-042":{"cognitivo":{"motivo":"Cobrar que a recuperação de falhas de armazenamento é função do backup, não do firewall.","mede":"Segurança da Informação — firewall x backup.","pegadinhaDesc":"A banca mistura dois conceitos sem relação direta (firewall e recuperação de dados).","ondeErra":"Acha que o firewall, por ser uma ferramenta de segurança, também armazena e restaura dados.","palavraCritica":"restauração do firewall ... preservar cópias","tecnica":"O firewall não armazena cópias de dados nem participa da recuperação de falhas de armazenamento — essa função é exercida pelos procedimentos de backup (cópias de segurança), que são conceitualmente distintos do firewall.","regraMental":"Recuperar dados após falha catastrófica = função do backup, nunca do firewall."},"comentario":{"resolucao":"ERRADO. O firewall é mecanismo de controle de tráfego de rede e não possui qualquer função de armazenamento ou preservação de cópias de dados — a recuperação de falhas catastróficas de armazenamento é realizada por meio da restauração de backups, e não do firewall.","fundamento":"Doutrina de segurança da informação — firewall x procedimentos de backup.","macete":"Quem recupera dados perdidos é o backup, nunca o firewall.","erroComum":"Misturar dois conceitos de segurança sem qualquer relação funcional entre si.","comoBancaPensa":"Combina dois conceitos sem relação direta para confundir o candidato menos atento."}},"TI-043":{"cognitivo":{"motivo":"Cobrar a existência de categorias especializadas de ferramentas antimalware.","mede":"Segurança da Informação — ferramentas antimalware.","pegadinhaDesc":"A banca pode negar a especialização por categoria ou inventar uma categoria inexistente.","ondeErra":"Estranha nomes menos comuns (antirootkit, antitrojan) e presume erro por desconhecimento do termo.","palavraCritica":"categorias especializadas","tecnica":"As soluções antimalware se dividem em categorias especializadas conforme o tipo de ameaça combatida: antivírus (vírus), antispyware (spyware), antirootkit (rootkits) e antitrojan (trojans) — soluções integradas também existem, combinando várias dessas funções.","regraMental":"Antimalware tem 'sobrenomes' — cada categoria mira uma ameaça específica."},"comentario":{"resolucao":"CERTO. As ferramentas antimalware realmente se organizam em categorias especializadas — antivírus, antispyware, antirootkit e antitrojan, entre outras —, cada uma voltada ao combate de um tipo específico de código malicioso, ainda que soluções integradas também sejam comuns no mercado.","fundamento":"Doutrina de segurança da informação — ferramentas antimalware.","macete":"Antimalware tem categorias por 'sobrenome': anti + tipo de ameaça.","erroComum":"Presumir erro só por desconhecer um termo técnico menos usual (ex.: antirootkit).","comoBancaPensa":"Item 'limpo' e tecnicamente correto — a banca não costuma inventar termos, mesmo os menos familiares."}},"TI-044":{"cognitivo":{"motivo":"Cobrar a definição correta do backup diferencial e sua simplicidade de restauração.","mede":"Segurança da Informação — procedimentos de backup (diferencial).","pegadinhaDesc":"A banca pode exigir todos os diferenciais em sequência (confundindo com o incremental).","ondeErra":"Troca o processo de restauração do diferencial pelo do incremental.","palavraCritica":"apenas ... o último backup diferencial","tecnica":"O backup diferencial sempre copia tudo o que mudou desde o último backup COMPLETO (por isso cresce a cada execução) — logo, para restaurar, basta o último completo somado ao último diferencial, sem necessidade de diferenciais anteriores.","regraMental":"Diferencial: restauração = último completo + último diferencial (simples)."},"comentario":{"resolucao":"CERTO. O backup diferencial copia todas as alterações ocorridas desde o último backup completo, de forma cumulativa. Por isso, sua restauração total é simples: exige apenas o último backup completo e o último backup diferencial, sem necessidade de diferenciais intermediários.","fundamento":"Doutrina de segurança da informação — tipos de backup (diferencial).","macete":"Diferencial: 2 peças para restaurar — completo + último diferencial.","erroComum":"Confundir a simplicidade de restauração do diferencial com a complexidade do incremental.","comoBancaPensa":"Cobra a definição exata e a vantagem prática do backup diferencial."}},"TI-045":{"cognitivo":{"motivo":"Cobrar, na forma invertida, a comparação de espaço e velocidade entre diferencial e incremental.","mede":"Segurança da Informação — procedimentos de backup (diferencial x incremental).","pegadinhaDesc":"A banca inverte a comparação: quem é mais rápido e consome menos espaço é o incremental, não o diferencial.","ondeErra":"Troca as vantagens de espaço/velocidade entre diferencial e incremental.","palavraCritica":"mais rápida ... menos espaço","tecnica":"O backup diferencial ACUMULA tudo desde o último completo, crescendo a cada dia da semana — por isso é mais LENTO e consome MAIS espaço ao longo do tempo do que o incremental, que copia apenas as mudanças desde o último backup (de qualquer tipo), sendo mais rápido e enxuto.","regraMental":"Diferencial cresce e acumula (mais espaço/mais lento). Incremental é enxuto (menos espaço/mais rápido)."},"comentario":{"resolucao":"ERRADO. É o inverso: o backup diferencial acumula as alterações desde o último completo, crescendo a cada execução ao longo da semana, sendo por isso mais lento e consumindo mais espaço do que o incremental — que copia apenas as mudanças desde o último backup realizado, sendo mais rápido e ocupando menos espaço.","fundamento":"Doutrina de segurança da informação — tipos de backup (comparação diferencial x incremental).","macete":"Diferencial cresce (mais espaço/lento). Incremental é enxuto (menos espaço/rápido).","erroComum":"Inverter a comparação de espaço e velocidade entre os dois tipos de backup.","comoBancaPensa":"Troca as características de dois tipos de backup na mesma frase — padrão clássico de erro."}},"TI-046":{"cognitivo":{"motivo":"Cobrar a definição correta do backup incremental e a complexidade de sua restauração.","mede":"Segurança da Informação — procedimentos de backup (incremental).","pegadinhaDesc":"A banca pode simplificar indevidamente a restauração do incremental (como se bastasse o último).","ondeErra":"Presume que a restauração do incremental é tão simples quanto a do diferencial.","palavraCritica":"todos os backups incrementais subsequentes, em sequência","tecnica":"O incremental copia só o que mudou desde o ÚLTIMO backup (de qualquer tipo), por isso é o mais econômico em espaço e mais rápido de executar. Em compensação, sua restauração é mais trabalhosa: exige o último completo MAIS todos os incrementais subsequentes, em ordem.","regraMental":"Incremental: economiza espaço/tempo no backup, mas complica a restauração (precisa de toda a cadeia)."},"comentario":{"resolucao":"CERTO. O backup incremental copia apenas as alterações desde o último backup (completo ou incremental), sendo o mais econômico em espaço de armazenamento — mas, justamente por isso, sua restauração completa exige o backup completo mais TODOS os incrementais subsequentes, aplicados em sequência.","fundamento":"Doutrina de segurança da informação — tipos de backup (incremental).","macete":"Incremental: economiza no backup, mas complica na restauração (precisa da cadeia toda).","erroComum":"Achar que a restauração do incremental é tão simples quanto a do diferencial.","comoBancaPensa":"Cobra o trade-off completo do incremental: vantagem no backup, desvantagem na restauração."}},"TI-047":{"cognitivo":{"motivo":"Cobrar, na forma invertida, o ranking de consumo de espaço entre os tipos de backup.","mede":"Segurança da Informação — procedimentos de backup (consumo de espaço).","pegadinhaDesc":"A banca troca o incremental (mais enxuto) pelo completo (que mais consome espaço).","ondeErra":"Não memoriza o ranking de consumo de espaço entre os três tipos de backup.","palavraCritica":"incremental ... mais consome espaço","tecnica":"O ranking de consumo de espaço é: completo (copia tudo, mais espaço) > diferencial (acumula desde o último completo) > incremental (só as mudanças mais recentes, menos espaço). O incremental é, portanto, o mais ECONÔMICO, não o que mais consome.","regraMental":"Espaço consumido: completo > diferencial > incremental."},"comentario":{"resolucao":"ERRADO. O tipo de backup que mais consome espaço de armazenamento é o completo, que copia todos os dados a cada execução. O incremental é, na verdade, o mais econômico em espaço, pois copia somente as alterações desde o último backup realizado.","fundamento":"Doutrina de segurança da informação — tipos de backup (consumo de espaço).","macete":"Ranking de espaço: completo > diferencial > incremental.","erroComum":"Trocar o incremental (mais econômico) pelo completo (que mais consome espaço).","comoBancaPensa":"Troca o tipo de backup no ranking de consumo de espaço, invertendo a ordem correta."}},"TI-048":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que o incremental não copia tudo a cada execução (isso é do backup completo).","mede":"Segurança da Informação — procedimentos de backup (incremental x completo).","pegadinhaDesc":"A banca atribui ao incremental a característica de 'cópia completa e recuperação rápida', que é do backup completo.","ondeErra":"Confunde a economia de espaço do incremental com uma suposta cópia integral a cada execução.","palavraCritica":"cópia exata e completa ... recuperação rápida e integral","tecnica":"O incremental copia SOMENTE as alterações desde o último backup, e não uma cópia completa a cada execução — quem oferece cópia integral e recuperação mais simples e rápida é o backup completo (full).","regraMental":"Cópia completa a cada execução = backup completo. Só as mudanças = incremental."},"comentario":{"resolucao":"ERRADO. O backup incremental copia apenas os arquivos alterados desde o último backup, e não uma cópia exata e completa de tudo a cada execução — essa característica, associada à recuperação mais rápida e simples, é típica do backup completo (full), não do incremental.","fundamento":"Doutrina de segurança da informação — tipos de backup (incremental x completo).","macete":"Cópia completa a cada vez = backup completo, nunca incremental.","erroComum":"Atribuir ao incremental as vantagens de simplicidade que são do backup completo.","comoBancaPensa":"Dá ao incremental a definição e as vantagens do backup completo."}},"TI-049":{"cognitivo":{"motivo":"Cobrar que a restauração do incremental é mais complexa que a do diferencial, exigindo toda a cadeia.","mede":"Segurança da Informação — procedimentos de backup (restauração).","pegadinhaDesc":"A banca equipara indevidamente a simplicidade de restauração do diferencial à do incremental.","ondeErra":"Não percebe que o incremental exige TODOS os incrementais em sequência, e não apenas o último.","palavraCritica":"assim como ... apenas dois conjuntos","tecnica":"Diferente do diferencial (que exige apenas o último completo + último diferencial), a restauração do incremental exige o último completo MAIS TODOS os incrementais subsequentes, aplicados em ordem cronológica — um processo mais longo e mais sujeito a falhas.","regraMental":"Diferencial: 2 peças. Incremental: completo + toda a cadeia de incrementais."},"comentario":{"resolucao":"ERRADO. Ao contrário do diferencial, a restauração completa a partir de backups incrementais exige o último backup completo E todos os backups incrementais realizados desde então, aplicados em sequência — não apenas dois conjuntos de arquivos.","fundamento":"Doutrina de segurança da informação — tipos de backup (restauração incremental x diferencial).","macete":"Incremental: restauração precisa de TODA a cadeia, não só do último.","erroComum":"Equiparar a simplicidade de restauração do diferencial à do incremental.","comoBancaPensa":"Estende indevidamente a vantagem do diferencial (restauração simples) ao incremental."}},"TI-050":{"cognitivo":{"motivo":"Cobrar que a nuvem reduz riscos, mas não elimina totalmente a ameaça de ransomware.","mede":"Segurança da Informação — computação em nuvem.","pegadinhaDesc":"A banca pode afirmar que a nuvem é totalmente imune a pragas virtuais.","ondeErra":"Presume que o armazenamento em nuvem elimina por completo qualquer risco de segurança.","palavraCritica":"não são totalmente imunes","tecnica":"A nuvem aumenta a resiliência dos dados (versionamento, cópias automáticas, redundância), mas não é totalmente imune — arquivos sincronizados podem ser afetados por ransomware que criptografa a pasta local espelhada, por exemplo.","regraMental":"Nuvem reduz risco, não elimina — desconfie de 'totalmente imune'."},"comentario":{"resolucao":"CERTO. Os serviços de nuvem realmente reduzem o risco de perda de dados e aumentam a resiliência, por meio de versionamento e cópias automáticas, mas não conferem imunidade total contra ameaças como o ransomware, que pode afetar também arquivos sincronizados.","fundamento":"Doutrina de segurança da informação — computação em nuvem e resiliência de dados.","macete":"Nuvem = mais resiliência, não imunidade total.","erroComum":"Achar que armazenar na nuvem elimina totalmente o risco de ataques.","comoBancaPensa":"Item correto e equilibrado, sem palavras absolutas — típico de item 'limpo'."}},"TI-051":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a nuvem não é totalmente imune a ransomware.","mede":"Segurança da Informação — computação em nuvem.","pegadinhaDesc":"A banca usa palavras absolutas ('totalmente imunes', 'por completo') para induzir ao erro.","ondeErra":"Aceita a afirmação de imunidade total sem questionar a plausibilidade técnica.","palavraCritica":"totalmente imunes","tecnica":"Não existe imunidade total: arquivos sincronizados com pastas locais infectadas por ransomware podem ter suas versões na nuvem também comprometidas, ainda que o versionamento permita, em muitos casos, restaurar versões anteriores.","regraMental":"Desconfie de 'totalmente imune' — a nuvem reduz risco, mas não zera."},"comentario":{"resolucao":"ERRADO. Os serviços de nuvem não são totalmente imunes a ransomware — eles reduzem o risco e aumentam a resiliência (por exemplo, via versionamento), mas não eliminam por completo a possibilidade de impacto em arquivos sincronizados.","fundamento":"Doutrina de segurança da informação — computação em nuvem e resiliência de dados.","macete":"'Totalmente imune' é quase sempre pegadinha em segurança da informação.","erroComum":"Aceitar afirmações de imunidade absoluta sem questionar sua plausibilidade.","comoBancaPensa":"Usa uma palavra absoluta clássica para sinalizar (para quem sabe identificar) que o item está errado."}},"TI-052":{"cognitivo":{"motivo":"Cobrar que o recurso de Arquivos sob Demanda do OneDrive não apaga sempre a cópia local.","mede":"Segurança da Informação — computação em nuvem (OneDrive).","pegadinhaDesc":"A banca usa a palavra absoluta 'sempre' para descrever um comportamento que é apenas uma das três possibilidades.","ondeErra":"Desconhece os três estados possíveis de um arquivo no recurso de Arquivos sob Demanda.","palavraCritica":"sempre apagada","tecnica":"O recurso Arquivos sob Demanda do OneDrive admite três estados para cada arquivo: somente na nuvem, disponível localmente e sempre disponível — o espaço local só é liberado quando necessário, e não por padrão/sempre.","regraMental":"OneDrive: 3 estados possíveis. Não existe 'sempre apaga a cópia local'."},"comentario":{"resolucao":"ERRADO. O recurso de Arquivos sob Demanda do OneDrive mantém três estados possíveis para cada arquivo (somente na nuvem, disponível localmente, sempre disponível), liberando o espaço local apenas quando necessário — a cópia local não é sempre apagada após a sincronização.","fundamento":"Doutrina de segurança da informação — computação em nuvem (OneDrive, Arquivos sob Demanda).","macete":"Palavra absoluta 'sempre' + comportamento configurável = pegadinha.","erroComum":"Presumir que a sincronização seletiva sempre remove a cópia local.","comoBancaPensa":"Usa uma palavra absoluta para transformar um recurso configurável em uma regra fixa inexistente."}},"TI-053":{"cognitivo":{"motivo":"Cobrar corretamente os três estados do recurso Arquivos sob Demanda.","mede":"Segurança da Informação — computação em nuvem (OneDrive).","pegadinhaDesc":"A banca pode negar a existência de múltiplos estados ou inventar um comportamento fixo.","ondeErra":"Desconhece o funcionamento real do recurso e presume um comportamento único.","palavraCritica":"três estados possíveis","tecnica":"O OneDrive permite que o usuário escolha, por arquivo ou pasta, entre mantê-lo somente na nuvem (sem ocupar espaço local), disponível localmente (baixado, mas liberável) ou sempre disponível (mantido localmente de forma permanente).","regraMental":"OneDrive: só na nuvem / disponível localmente / sempre disponível — três estados configuráveis."},"comentario":{"resolucao":"CERTO. O recurso de Arquivos sob Demanda do OneDrive realmente admite três estados possíveis para cada arquivo — somente na nuvem, disponível localmente e sempre disponível —, permitindo liberar espaço de armazenamento local apenas quando necessário, sem apagar arquivos por padrão.","fundamento":"Doutrina de segurança da informação — computação em nuvem (OneDrive, Arquivos sob Demanda).","macete":"3 estados do OneDrive: nuvem / local liberável / sempre local.","erroComum":"Achar que existe apenas um comportamento fixo (arquivo sempre local ou sempre na nuvem).","comoBancaPensa":"Item de fixação técnica sobre um recurso específico e configurável."}},"TI-054":{"cognitivo":{"motivo":"Cobrar a identificação correta de um ataque DDoS a partir de sua descrição técnica.","mede":"Segurança da Informação — ataques de negação de serviço (DDoS).","pegadinhaDesc":"A banca pode nomear corretamente a descrição ou trocar por outro tipo de ataque (ex.: ransomware).","ondeErra":"Não associa a descrição técnica (volume + múltiplas origens + sobrecarga) ao nome correto do ataque.","palavraCritica":"DDoS","tecnica":"O ataque de negação de serviço distribuído (DDoS) caracteriza-se pelo envio maciço e simultâneo de requisições, a partir de múltiplas origens (muitas vezes uma botnet), com o objetivo de esgotar os recursos do alvo e comprometer o princípio da disponibilidade.","regraMental":"Volume massivo + múltiplas origens + sobrecarga = DDoS, atacando a disponibilidade."},"comentario":{"resolucao":"CERTO. A descrição corresponde exatamente a um ataque de negação de serviço distribuído (DDoS): volume massivo de conexões simultâneas, provenientes de múltiplas origens distribuídas, com o objetivo de exceder a capacidade do serviço-alvo e comprometer sua disponibilidade.","fundamento":"Doutrina de segurança da informação — ataques de negação de serviço (DDoS).","macete":"DDoS: muitas origens + volume + objetivo de derrubar o serviço (disponibilidade).","erroComum":"Confundir a descrição técnica correta com outro tipo de ataque.","comoBancaPensa":"Item 'limpo', com a descrição batendo exatamente com o nome técnico do ataque."}},"TI-055":{"cognitivo":{"motivo":"Cobrar que a descrição de um ataque volumétrico/DDoS não deve ser nomeada como ransomware.","mede":"Segurança da Informação — ataques de negação de serviço x ransomware.","pegadinhaDesc":"A banca descreve um DDoS com precisão técnica, mas nomeia o ataque como 'ransomware'.","ondeErra":"Concorda com o nome do ataque só porque a descrição técnica anterior parece coerente, sem verificar se o nome bate com a descrição.","palavraCritica":"classificado como ... ransomware","tecnica":"A descrição (volume massivo, múltiplas origens, sobrecarga, interrupção do serviço) corresponde a um ataque de negação de serviço distribuído (DDoS), que compromete a disponibilidade — o ransomware, por sua vez, consiste em criptografar dados e exigir resgate, sem qualquer relação com volume de conexões.","regraMental":"Descrição de sobrecarga de tráfego = DDoS, nunca ransomware."},"comentario":{"resolucao":"ERRADO. A situação descrita — volume massivo de conexões simultâneas de múltiplas origens, com o objetivo de sobrecarregar e derrubar um serviço — caracteriza um ataque de negação de serviço distribuído (DDoS), e não um ataque de ransomware, que consiste em criptografar dados e exigir resgate, sem relação com volume de tráfego.","fundamento":"Doutrina de segurança da informação — ataques de negação de serviço (DDoS) x ransomware.","macete":"Sobrecarga de tráfego derrubando serviço = DDoS. Criptografia + resgate = ransomware.","erroComum":"Aceitar o nome do ataque proposto pela banca mesmo quando a descrição técnica não corresponde a ele.","comoBancaPensa":"Descreve corretamente um ataque, mas atribui a ele o nome de outro tipo de ameaça completamente distinto."}},"TI-056":{"cognitivo":{"motivo":"Cobrar, na forma invertida, a distinção entre DoS (origem única) e DDoS (origem distribuída).","mede":"Segurança da Informação — DoS x DDoS (origem do ataque).","pegadinhaDesc":"A banca inverte as definições de DoS e DDoS quanto à origem do ataque.","ondeErra":"Troca a definição de DoS (origem única) pela de DDoS (origem distribuída), e vice-versa.","palavraCritica":"DoS ... múltiplos computadores","tecnica":"O DoS (Denial of Service) parte de UMA ÚNICA origem/máquina atacante. Já o DDoS (Distributed Denial of Service) é justamente a versão distribuída, partindo de MÚLTIPLAS origens (frequentemente uma botnet) simultaneamente — o prefixo 'D' de DDoS indica exatamente essa distribuição.","regraMental":"DoS = uma origem. DDoS = múltiplas origens distribuídas (o 'D' extra é disso)."},"comentario":{"resolucao":"ERRADO. As definições foram invertidas: o DoS (Denial of Service) tem origem em uma única máquina atacante, enquanto o DDoS (Distributed Denial of Service) é a versão distribuída do ataque, partindo de múltiplos computadores/origens coordenados simultaneamente.","fundamento":"Doutrina de segurança da informação — ataques de negação de serviço (DoS x DDoS).","macete":"O 'D' extra de DDoS = distribuído = múltiplas origens.","erroComum":"Inverter as definições de DoS e DDoS quanto à quantidade de origens do ataque.","comoBancaPensa":"Testa a distinção mais básica e recorrente entre as duas siglas parecidas."}},"TI-057":{"cognitivo":{"motivo":"Cobrar a extensão da tríade CID com autenticidade e não repúdio, e o papel da assinatura digital.","mede":"Segurança da Informação — fundamentos (tríade CID e princípios complementares).","pegadinhaDesc":"A banca pode negar a existência desses princípios complementares ou atribuí-los a outra ferramenta.","ondeErra":"Restringe a segurança da informação apenas aos três pilares da tríade CID, ignorando autenticidade e não repúdio.","palavraCritica":"autenticidade e o não repúdio","tecnica":"Além da tríade CID (confidencialidade, integridade, disponibilidade), a doutrina reconhece a autenticidade (garantia da identidade de quem envia/assina a informação) e o não repúdio (impossibilidade de negar a autoria de um ato) como princípios complementares, ambos viabilizados tecnicamente pela assinatura digital.","regraMental":"5 pilares: CID + autenticidade + não repúdio. Assinatura digital garante os dois últimos."},"comentario":{"resolucao":"CERTO. Além da tríade CID, a autenticidade (garantia da identidade do emissor) e o não repúdio (impossibilidade de negar a autoria de uma ação) completam o conjunto clássico de premissas da segurança da informação, sendo ambos assegurados, na prática, pelo uso da assinatura digital.","fundamento":"Doutrina de segurança da informação — princípios complementares à tríade CID (autenticidade e não repúdio).","macete":"CID + autenticidade + não repúdio = 5 pilares. Assinatura digital garante os dois últimos.","erroComum":"Restringir a segurança da informação apenas aos três pilares da tríade CID.","comoBancaPensa":"Amplia o conhecimento exigido para além da tríade básica, cobrando os princípios complementares."}},"TI-058":{"cognitivo":{"motivo":"Cobrar as definições corretas e completas de integridade e disponibilidade.","mede":"Segurança da Informação — fundamentos (tríade CID).","pegadinhaDesc":"A banca pode inverter as duas definições ou generalizar 'disponibilidade' para acesso irrestrito.","ondeErra":"Interpreta 'disponibilidade' como acesso permanente e irrestrito a qualquer pessoa, e não apenas aos autorizados quando necessário.","palavraCritica":"acessíveis sempre que necessários ... autorizados","tecnica":"Integridade: os dados devem permanecer exatos e não sofrer alteração indevida (garantida por hash e assinatura digital). Disponibilidade: o acesso deve ser garantido aos USUÁRIOS AUTORIZADOS sempre que necessário — não significa acesso ilimitado a qualquer pessoa, a qualquer momento.","regraMental":"Integridade = dado correto. Disponibilidade = acesso a quem tem direito, quando precisar."},"comentario":{"resolucao":"CERTO. A integridade garante que os dados permaneçam completos e não sejam alterados indevidamente, enquanto a disponibilidade assegura que sistemas e informações estejam acessíveis sempre que necessário, mas apenas aos usuários devidamente autorizados — não a qualquer pessoa, de forma irrestrita.","fundamento":"Doutrina de segurança da informação — fundamentos (tríade CID: integridade e disponibilidade).","macete":"Disponibilidade é para quem tem autorização — não é acesso público irrestrito.","erroComum":"Achar que disponibilidade significa acesso livre e permanente a qualquer usuário.","comoBancaPensa":"Item de fixação sobre as definições completas e corretas de dois pilares da tríade CID."}},"TI-059":{"cognitivo":{"motivo":"Cobrar o reconhecimento direto da tríade CID como fundamento básico da segurança da informação.","mede":"Segurança da Informação — fundamentos (tríade CID).","pegadinhaDesc":"A banca pode trocar um dos três atributos por outro conceito (ex.: autenticidade no lugar da disponibilidade).","ondeErra":"Confunde os três pilares básicos com os princípios complementares (autenticidade e não repúdio).","palavraCritica":"confidencialidade, integridade e disponibilidade","tecnica":"A tríade CID (ou CIA, em inglês) — confidencialidade, integridade e disponibilidade — constitui o conjunto de atributos mais básicos e fundamentais da segurança da informação, servindo de base para todos os controles e políticas de proteção de dados.","regraMental":"CID: Confidencialidade, Integridade, Disponibilidade — os 3 pilares básicos e mais cobrados."},"comentario":{"resolucao":"CERTO. A confidencialidade, a integridade e a disponibilidade constituem, de fato, os atributos básicos e fundamentais da segurança da informação, formando a conhecida tríade CID (ou CIA), sobre a qual se apoiam os demais princípios e controles de proteção de dados.","fundamento":"Doutrina de segurança da informação — fundamentos (tríade CID).","macete":"CID: a base de tudo em segurança da informação — decore os três nomes.","erroComum":"Confundir os três pilares básicos com os princípios complementares (autenticidade, não repúdio).","comoBancaPensa":"Item de fixação direto e de alta recorrência, sem qualquer pegadinha de cruzamento de conceitos."}},"TI-060":{"cognitivo":{"motivo":"Cobrar o recurso de criação de pastas no Menu Iniciar do Windows 11 e a diferença em relação ao Windows 10.","mede":"Informática — Sistemas Operacionais (Windows 11, Menu Iniciar).","pegadinhaDesc":"A banca pode negar a existência desse recurso ou atribuí-lo também ao Windows 10.","ondeErra":"Acha que o recurso de pastas por arraste já existia da mesma forma no Windows 10.","palavraCritica":"criar automaticamente uma pasta ... Live Tiles","tecnica":"No Windows 11, arrastar um ícone de app fixado sobre outro cria uma pasta automaticamente (que pode ser renomeada), de forma semelhante a smartphones. O Windows 10 não tinha essa estrutura de pastas compactas, organizando os apps fixados apenas em grupos de blocos dinâmicos (Live Tiles).","regraMental":"Windows 11: arrastar ícone sobre ícone = pasta. Windows 10: só Live Tiles, sem pastas assim."},"comentario":{"resolucao":"CERTO. No Windows 11, arrastar um ícone sobre outro na seção de aplicativos fixados cria automaticamente uma pasta, recurso que não existia dessa forma no Windows 10, que organizava os aplicativos fixados apenas em grupos de blocos dinâmicos (Live Tiles).","fundamento":"Doutrina de Informática — Sistemas Operacionais (recursos do Menu Iniciar do Windows 11).","macete":"Pastas no Menu Iniciar = novidade do Windows 11, não existia no 10.","erroComum":"Achar que o recurso de pastas por arraste também existia no Windows 10.","comoBancaPensa":"Item 'limpo' que descreve corretamente uma novidade visual do Windows 11 em comparação ao antecessor."}},"TI-061":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que é justamente o Windows 11 (e não o 10) que introduziu as pastas de aplicativos fixados.","mede":"Informática — Sistemas Operacionais (Windows 11, Menu Iniciar).","pegadinhaDesc":"A banca inverte a atribuição do recurso, colocando no Windows 10 uma funcionalidade do Windows 11.","ondeErra":"Troca o sistema que possui o recurso: atribui ao Windows 10 uma novidade que é do Windows 11.","palavraCritica":"exclusivo do Windows 10","tecnica":"É o Windows 11 que permite criar pastas por arraste de ícones no Menu Iniciar. O Windows 10, por sua vez, organizava os aplicativos fixados apenas em grupos de blocos dinâmicos (Live Tiles), sem essa estrutura de pastas.","regraMental":"Pastas no Menu Iniciar = Windows 11. Live Tiles sem pastas = Windows 10."},"comentario":{"resolucao":"ERRADO. É o Windows 11, e não o Windows 10, que permite a criação de pastas para organizar os ícones dos aplicativos fixados no Menu Iniciar. O Windows 10 organizava os aplicativos fixados apenas em grupos de blocos dinâmicos (Live Tiles), sem essa estrutura de pastas.","fundamento":"Doutrina de Informática — Sistemas Operacionais (recursos do Menu Iniciar do Windows 11).","macete":"Pastas no Menu Iniciar = Windows 11 (novidade), não o Windows 10.","erroComum":"Inverter qual versão do Windows introduziu o recurso de pastas no Menu Iniciar.","comoBancaPensa":"Troca o sujeito da afirmação (Windows 11 → Windows 10) para induzir o erro."}},"TI-062":{"cognitivo":{"motivo":"Cobrar o novo design centralizado da barra de tarefas do Windows 11 e a possibilidade de personalização.","mede":"Informática — Sistemas Operacionais (Windows 11, barra de tarefas).","pegadinhaDesc":"A banca pode negar a possibilidade de realinhamento à esquerda, tratando o layout centralizado como fixo.","ondeErra":"Acha que o layout centralizado é definitivo e não pode ser alterado pelo usuário.","palavraCritica":"por padrão ... possível ... realinhar","tecnica":"No Windows 11, os ícones da barra de tarefas, incluindo o botão Iniciar, vêm centralizados por padrão. É possível realinhá-los à esquerda por meio de Configurações → Personalização → Barra de tarefas → Comportamentos da barra de tarefas → Alinhamento.","regraMental":"Windows 11: centralizado é o padrão, mas dá para voltar à esquerda nas configurações."},"comentario":{"resolucao":"CERTO. No Windows 11, os ícones da barra de tarefas, incluindo o botão Iniciar, vêm centralizados por padrão, sendo possível realinhá-los à esquerda por meio das configurações da barra de tarefas, para quem prefere o estilo tradicional do Windows 10.","fundamento":"Doutrina de Informática — Sistemas Operacionais (barra de tarefas do Windows 11).","macete":"Centralizado é só o padrão — dá para mudar para a esquerda nas configurações.","erroComum":"Achar que o alinhamento centralizado é fixo e não pode ser alterado.","comoBancaPensa":"Item 'limpo' que combina a descrição do padrão visual com a possibilidade de personalização."}},"TI-063":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que o alinhamento centralizado do Windows 11 pode ser alterado pelo usuário.","mede":"Informática — Sistemas Operacionais (Windows 11, barra de tarefas).","pegadinhaDesc":"A banca afirma que a centralização é exclusiva e imutável, ignorando a opção de personalização.","ondeErra":"Aceita a ideia de que o layout do Windows 11 não pode ser configurado pelo usuário.","palavraCritica":"exclusivamente ... não havendo ... qualquer opção","tecnica":"Embora o layout centralizado seja o padrão do Windows 11, o sistema oferece, em Configurações → Personalização → Barra de tarefas, a opção de realinhar os ícones à esquerda, revertendo ao estilo usado no Windows 10.","regraMental":"Centralizado é padrão, não é exclusivo — a opção de mudar para a esquerda existe."},"comentario":{"resolucao":"ERRADO. Embora o layout centralizado seja o padrão do Windows 11, o sistema permite, por meio das configurações da barra de tarefas, realinhar os ícones à esquerda — a centralização não é exclusiva nem imutável, ao contrário do que afirma o item.","fundamento":"Doutrina de Informática — Sistemas Operacionais (barra de tarefas do Windows 11).","macete":"Nunca existe 'sem opção nenhuma' quando se trata de configuração de interface no Windows 11.","erroComum":"Tratar o padrão visual do sistema como uma imposição sem alternativa de personalização.","comoBancaPensa":"Usa 'exclusivamente' e 'qualquer opção' para transformar um padrão configurável em algo fixo."}},"TI-064":{"cognitivo":{"motivo":"Cobrar a definição correta do Snap Layouts e suas formas de acionamento.","mede":"Informática — Sistemas Operacionais (Windows 11, Snap Layouts).","pegadinhaDesc":"A banca pode trocar o atalho de acionamento (ex.: Windows+Tab, que é a Visão de Tarefas).","ondeErra":"Confunde o atalho do Snap Layouts (Windows+Z) com o da Visão de Tarefas (Windows+Tab).","palavraCritica":"Windows+Z ... botão Maximizar","tecnica":"O Snap Layouts organiza várias janelas em layouts predefinidos na tela, sem necessidade de redimensionamento manual, podendo ser acionado pelo atalho Windows+Z, ao passar o mouse sobre o botão Maximizar, ou arrastando a janela até o topo da tela.","regraMental":"Snap Layouts = Win+Z ou mouse no Maximizar. Não confundir com Win+Tab (Visão de Tarefas)."},"comentario":{"resolucao":"CERTO. O Snap Layouts oferece opções predefinidas para organizar várias janelas na tela de forma eficiente, podendo ser acionado pelo atalho Windows+Z ou ao posicionar o cursor sobre o botão Maximizar de uma janela, entre outras formas.","fundamento":"Doutrina de Informática — Sistemas Operacionais (Snap Layouts do Windows 11).","macete":"Snap Layouts: Win+Z ou passar o mouse no Maximizar.","erroComum":"Confundir o atalho do Snap Layouts com o da Visão de Tarefas (Windows+Tab).","comoBancaPensa":"Item 'limpo' sobre um recurso amplamente cobrado do Windows 11."}},"TI-065":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que o Snap Layouts é acionado por Windows+Z, e não por Windows+Tab (atalho da Visão de Tarefas).","mede":"Informática — Sistemas Operacionais (Windows 11, Snap Layouts x Visão de Tarefas).","pegadinhaDesc":"A banca troca o atalho correto do Snap Layouts pelo atalho de outro recurso (Visão de Tarefas).","ondeErra":"Confunde Snap Layouts (organização de janelas em layouts) com Visão de Tarefas (alternância entre janelas/áreas de trabalho).","palavraCritica":"Windows+Tab","tecnica":"O atalho Windows+Z é que aciona o Snap Layouts. O atalho Windows+Tab abre a Visão de Tarefas, recurso distinto, usado para alternar entre janelas abertas e áreas de trabalho virtuais — não para organizar janelas em layouts predefinidos.","regraMental":"Win+Z = Snap Layouts. Win+Tab = Visão de Tarefas. São recursos diferentes."},"comentario":{"resolucao":"ERRADO. O Snap Layouts é acionado pelo atalho Windows+Z (entre outras formas), e não por Windows+Tab. Este último abre a Visão de Tarefas, recurso distinto, destinado à alternância entre janelas abertas e áreas de trabalho virtuais.","fundamento":"Doutrina de Informática — Sistemas Operacionais (Snap Layouts x Visão de Tarefas no Windows 11).","macete":"Win+Z = organizar janelas (Snap). Win+Tab = trocar de janela (Visão de Tarefas).","erroComum":"Trocar o atalho do Snap Layouts pelo da Visão de Tarefas.","comoBancaPensa":"Troca dois conceitos próximos (ambos relacionados a gerenciamento de janelas) e seus respectivos atalhos."}},"TI-066":{"cognitivo":{"motivo":"Cobrar que renomear a extensão de um arquivo não converte seu conteúdo real.","mede":"Informática — Sistemas Operacionais (Windows Explorer, extensões de arquivo).","pegadinhaDesc":"A banca pode afirmar que o Windows ajusta os metadados e a estrutura do arquivo ao renomear a extensão.","ondeErra":"Acha que renomear a extensão converte automaticamente o formato real do arquivo.","palavraCritica":"apenas modifica o rótulo ... sem converter","tecnica":"Renomear a extensão de um arquivo no Windows Explorer altera apenas o texto do nome exibido — não converte o conteúdo binário nem ajusta a estrutura interna do arquivo. Um .jpg renomeado para .png continua sendo, internamente, um arquivo JPEG, podendo apresentar problemas ao ser aberto por programas que esperam o formato PNG.","regraMental":"Trocar extensão = trocar só o nome. O conteúdo interno do arquivo não muda."},"comentario":{"resolucao":"CERTO. Renomear a extensão de um arquivo no Windows Explorer apenas altera o rótulo do nome exibido, sem converter seu conteúdo nem ajustar sua estrutura interna — o arquivo pode, inclusive, ficar inconsistente ou não abrir corretamente no novo formato indicado pelo nome.","fundamento":"Doutrina de Informática — Sistemas Operacionais (Windows Explorer, manipulação de extensões de arquivo).","macete":"Renomear extensão ≠ converter arquivo. Conversão real exige software específico.","erroComum":"Achar que o Windows ajusta a estrutura do arquivo automaticamente ao trocar a extensão no nome.","comoBancaPensa":"Item 'limpo' sobre uma pegadinha clássica: rótulo do nome x conteúdo real do arquivo."}},"TI-067":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que o Windows não converte o conteúdo do arquivo apenas por renomear a extensão.","mede":"Informática — Sistemas Operacionais (Windows Explorer, extensões de arquivo).","pegadinhaDesc":"A banca afirma que a simples troca de extensão no nome converte automaticamente o conteúdo do arquivo.","ondeErra":"Confunde a alteração do rótulo do nome do arquivo com uma conversão real de formato.","palavraCritica":"ajusta automaticamente ... convertendo seu conteúdo","tecnica":"O Windows Explorer apenas altera o texto do nome do arquivo ao renomear sua extensão, sem ajustar metadados nem converter o conteúdo interno. A conversão real de formato exige um software apropriado (por exemplo, um editor de imagens), e não ocorre apenas ao renomear o arquivo.","regraMental":"Renomear extensão nunca converte o arquivo de verdade — sempre precisa de software específico."},"comentario":{"resolucao":"ERRADO. Renomear a extensão de um arquivo no Windows Explorer apenas altera o rótulo do nome — não converte o conteúdo nem ajusta metadados ou estrutura interna. A conversão real de formato exige um software apropriado, e não ocorre automaticamente apenas com a renomeação.","fundamento":"Doutrina de Informática — Sistemas Operacionais (Windows Explorer, manipulação de extensões de arquivo).","macete":"Renomear extensão ≠ converter arquivo, mesmo que o item diga 'automaticamente'.","erroComum":"Acreditar que o sistema operacional converte o conteúdo do arquivo ao mudar sua extensão no nome.","comoBancaPensa":"Repete a pegadinha clássica de forma afirmativa, na tentativa de induzir o candidato ao erro pela repetição."}},"TI-068":{"cognitivo":{"motivo":"Cobrar o funcionamento correto das passkeys integradas ao Windows Hello.","mede":"Informática — Sistemas Operacionais (Windows 11, Windows Hello e passkeys).","pegadinhaDesc":"A banca pode afirmar que esse processo torna a autenticação menos segura, invertendo a lógica do recurso.","ondeErra":"Acha que dispensar a senha, por si só, torna o processo menos seguro.","palavraCritica":"sem necessidade de digitar senhas ... mais seguro","tecnica":"O Windows Hello permite autenticação por biometria (impressão digital, reconhecimento facial) ou PIN. As chaves de acesso (passkeys) permitem entrar em sites e aplicativos sem digitar senha, sendo essa combinação considerada mais rápida e mais segura do que a autenticação tradicional por senha.","regraMental":"Passkeys + Windows Hello = login sem senha, mais rápido e mais seguro (não o contrário)."},"comentario":{"resolucao":"CERTO. As chaves de acesso (passkeys), integradas ao Windows Hello, permitem iniciar sessão em sites e aplicativos por biometria ou PIN, sem necessidade de digitar senhas — tornando o processo de autenticação mais rápido e mais seguro do que o uso tradicional de senhas.","fundamento":"Doutrina de Informática — Sistemas Operacionais (Windows Hello e chaves de acesso no Windows 11).","macete":"Sem senha, com biometria/PIN = mais seguro, não menos.","erroComum":"Achar que a ausência de senha torna o login menos seguro.","comoBancaPensa":"Item 'limpo' descrevendo corretamente um recurso moderno de autenticação do Windows 11."}},"TI-069":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que as passkeys tornam o login mais seguro, e não menos.","mede":"Informática — Sistemas Operacionais (Windows 11, Windows Hello e passkeys).","pegadinhaDesc":"A banca parte de uma premissa verdadeira (dispensa de senha) para chegar a uma conclusão falsa (menos segurança).","ondeErra":"Assume que eliminar a senha necessariamente reduz a segurança do processo de autenticação.","palavraCritica":"tornam o processo ... menos seguro","tecnica":"As chaves de acesso (passkeys) substituem a senha por biometria (impressão digital, reconhecimento facial) ou PIN vinculados ao dispositivo, o que é considerado mais seguro do que senhas tradicionais — que podem ser furtadas, reutilizadas ou descobertas por engenharia social.","regraMental":"Passkey substitui senha por biometria/PIN — isso aumenta a segurança, não diminui."},"comentario":{"resolucao":"ERRADO. As chaves de acesso (passkeys) tornam o processo de autenticação mais seguro, e não menos — a dispensa da senha ocorre porque a biometria ou o PIN vinculado ao dispositivo oferece proteção superior às senhas tradicionais, que podem ser furtadas ou reutilizadas indevidamente.","fundamento":"Doutrina de Informática — Sistemas Operacionais (Windows Hello e chaves de acesso no Windows 11).","macete":"Passkey = mais segurança, não menos, mesmo sem senha.","erroComum":"Associar automaticamente 'sem senha' a 'menos seguro'.","comoBancaPensa":"Parte de um fato correto (dispensa de senha) para chegar a uma conclusão errada sobre segurança."}},"TI-070":{"cognitivo":{"motivo":"Cobrar que o Windows Update automático permanece ativo no Windows 11, com opção apenas de pausa temporária.","mede":"Informática — Sistemas Operacionais (Windows 11, Windows Update).","pegadinhaDesc":"A banca pode afirmar que o Windows 11 não instala mais atualizações automaticamente.","ondeErra":"Acha que o Windows 11 eliminou o processo automático de atualização, exigindo ação manual do usuário.","palavraCritica":"continua aplicando ... automaticamente ... pausar temporariamente","tecnica":"O Windows 11 mantém as atualizações automáticas por meio do Windows Update (Configurações → Windows Update), permitindo apenas verificar manualmente a disponibilidade de novas atualizações ou pausar o processo por um período — sem uma forma simples de desativá-lo definitivamente.","regraMental":"Windows 11 sempre atualiza sozinho — só dá para pausar por um tempo, não desligar de vez."},"comentario":{"resolucao":"CERTO. O Windows 11 continua aplicando atualizações automaticamente por meio do Windows Update, sendo possível ao usuário apenas verificar manualmente novas atualizações ou pausar temporariamente o processo — não havendo forma simples de desativá-lo por completo.","fundamento":"Doutrina de Informática — Sistemas Operacionais (Windows Update no Windows 11).","macete":"Windows Update: sempre automático; só dá para pausar, não desligar de vez.","erroComum":"Achar que o Windows 11 passou a depender de verificação manual para se atualizar.","comoBancaPensa":"Item 'limpo' que corrige uma crença comum equivocada sobre o funcionamento do Windows Update."}},"TI-071":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que o Windows Update automático não foi removido do Windows 11.","mede":"Informática — Sistemas Operacionais (Windows 11, Windows Update).","pegadinhaDesc":"A banca afirma que as atualizações automáticas foram eliminadas por questões de segurança, o que é falso.","ondeErra":"Aceita a premissa de que a verificação manual substituiu totalmente o processo automático de atualização.","palavraCritica":"não permite mais ... obrigatoriamente","tecnica":"O Windows 11 mantém o processo de atualizações automáticas por meio do Windows Update. A verificação manual em Configurações → Windows Update é apenas uma opção adicional, e não uma obrigação decorrente da suposta eliminação do processo automático — que, na realidade, não ocorreu.","regraMental":"Windows 11 nunca deixou de atualizar sozinho — a verificação manual é só uma opção extra."},"comentario":{"resolucao":"ERRADO. O Windows 11 mantém as atualizações automáticas por meio do Windows Update. A afirmação de que ele 'não permite mais' atualizações automáticas é falsa — a verificação manual existe como opção adicional, mas não substitui nem foi motivada pela eliminação do processo automático.","fundamento":"Doutrina de Informática — Sistemas Operacionais (Windows Update no Windows 11).","macete":"Windows Update automático nunca foi removido do Windows 11.","erroComum":"Acreditar que a existência de verificação manual implica a extinção do processo automático.","comoBancaPensa":"Usa uma justificativa plausível ('questões de segurança') para tornar crível uma afirmação factualmente falsa."}},"TI-072":{"cognitivo":{"motivo":"Cobrar a localização correta do recurso Sessões de foco (app Relógio) e sua integração com o Assistente de Foco.","mede":"Informática — Sistemas Operacionais (Windows 11, Sessões de foco).","pegadinhaDesc":"A banca pode atribuir o recurso a outro local do sistema, como o Painel de Controle.","ondeErra":"Acha que o recurso de bloqueio de notificações fica no Painel de Controle, e não no app Relógio.","palavraCritica":"aplicativo Relógio","tecnica":"O recurso Sessões de foco está disponível no aplicativo Relógio do Windows 11, permitindo bloquear temporariamente notificações, sons e alertas de aplicativos por um período definido pelo usuário, integrando-se ao Assistente de Foco (também chamado de Não Perturbe).","regraMental":"Sessões de foco ficam no app Relógio, integradas ao Assistente de Foco/Não Perturbe."},"comentario":{"resolucao":"CERTO. O aplicativo Relógio do Windows 11 disponibiliza o recurso Sessões de foco, que permite bloquear temporariamente notificações, sons e alertas de aplicativos por um período definido, integrando-se ao Assistente de Foco (Não Perturbe).","fundamento":"Doutrina de Informática — Sistemas Operacionais (Sessões de foco no Windows 11).","macete":"Sessões de foco = app Relógio, não Painel de Controle.","erroComum":"Localizar o recurso de bloqueio de notificações em um app diferente do Relógio.","comoBancaPensa":"Item 'limpo' sobre a localização e a integração de um recurso específico do Windows 11."}},"TI-073":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que as Sessões de foco ficam no app Relógio, e não no Painel de Controle.","mede":"Informática — Sistemas Operacionais (Windows 11, Sessões de foco).","pegadinhaDesc":"A banca localiza o recurso em um local desatualizado (Painel de Controle clássico), incompatível com a proposta.","ondeErra":"Confunde o Painel de Controle clássico (herdado de versões antigas do Windows) com os aplicativos nativos modernos do Windows 11.","palavraCritica":"exclusivamente no Painel de Controle","tecnica":"As Sessões de foco são um recurso do aplicativo Relógio, um app nativo moderno do Windows 11 — e não do Painel de Controle clássico, que reúne configurações herdadas de versões anteriores do sistema.","regraMental":"Sessões de foco = app Relógio (moderno), não Painel de Controle (clássico)."},"comentario":{"resolucao":"ERRADO. O recurso Sessões de foco está disponível no aplicativo Relógio, um app nativo moderno do Windows 11, e não no Painel de Controle clássico, que reúne configurações herdadas de versões anteriores do sistema.","fundamento":"Doutrina de Informática — Sistemas Operacionais (Sessões de foco no Windows 11).","macete":"Sessões de foco: app Relógio, não Painel de Controle.","erroComum":"Confundir os aplicativos modernos do Windows 11 com o Painel de Controle clássico.","comoBancaPensa":"Atribui o recurso a um componente legado do sistema, incompatível com a proposta moderna do app Relógio."}},"TI-074":{"cognitivo":{"motivo":"Cobrar que o Windows possui renomeação em lote nativa, sem depender de software de terceiros.","mede":"Informática — Sistemas Operacionais (Windows Explorer, renomeação de arquivos em lote).","pegadinhaDesc":"A banca pode afirmar que esse recurso exige a instalação de um programa adicional.","ondeErra":"Acha que renomear vários arquivos com um padrão de nome só é possível com software externo.","palavraCritica":"sem necessidade de instalar programas adicionais","tecnica":"No Windows Explorer, ao selecionar vários arquivos e pressionar F2, é possível definir um nome-base para todos eles; o sistema numera automaticamente os itens em sequência (nome (1), nome (2)...), recurso nativo que dispensa qualquer programa adicional.","regraMental":"Selecionar vários + F2 = renomeação em lote nativa do Windows, sem programa externo."},"comentario":{"resolucao":"CERTO. O Windows possui função nativa de renomeação em lote: ao selecionar vários arquivos e pressionar F2, o usuário define um nome-base, e o sistema numera automaticamente os itens em sequência, sem necessidade de instalar programas adicionais.","fundamento":"Doutrina de Informática — Sistemas Operacionais (Windows Explorer, renomeação em lote).","macete":"F2 em vários arquivos selecionados = renomeação em lote nativa.","erroComum":"Achar que esse recurso depende de um software de terceiros.","comoBancaPensa":"Item 'limpo' sobre um recurso nativo pouco conhecido, mas frequentemente cobrado."}},"TI-075":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que o Windows já tem renomeação em lote nativa, sem exigir software externo.","mede":"Informática — Sistemas Operacionais (Windows Explorer, renomeação de arquivos em lote).","pegadinhaDesc":"A banca cria uma exigência inexistente (necessidade de programa de terceiros) para uma tarefa já suportada nativamente.","ondeErra":"Ignora que selecionar vários arquivos e pressionar F2 já resolve a renomeação em lote sem qualquer instalação.","palavraCritica":"necessário ... programas adicionais","tecnica":"O Windows Explorer permite renomear vários arquivos simultaneamente com um padrão comum de nomes de forma nativa: basta selecionar os arquivos, pressionar F2 e definir um nome-base — o sistema numera automaticamente os itens, sem qualquer necessidade de programas de terceiros.","regraMental":"Renomear em lote é nativo do Windows — não precisa de programa nenhum."},"comentario":{"resolucao":"ERRADO. O Windows possui, sim, função nativa de renomeação em lote: basta selecionar vários arquivos, pressionar F2 e definir um nome-base, que o sistema numerará automaticamente — não há necessidade de instalar programas de terceiros para essa finalidade.","fundamento":"Doutrina de Informática — Sistemas Operacionais (Windows Explorer, renomeação em lote).","macete":"F2 + seleção múltipla já resolve — nenhum programa extra é necessário.","erroComum":"Criar uma exigência de software externo para uma funcionalidade já nativa do sistema.","comoBancaPensa":"Cria uma falsa necessidade de ferramenta externa para uma tarefa que o próprio Windows já resolve."}},"TI-076":{"cognitivo":{"motivo":"Cobrar a boa prática de nomeação descritiva de arquivos para facilitar busca e organização.","mede":"Informática — Gestão e organização de arquivos (boas práticas de nomeação).","pegadinhaDesc":"A banca pode afirmar que nomes genéricos facilitam a busca, invertendo a lógica da boa prática.","ondeErra":"Acha que nomes curtos e genéricos, por serem simples, favorecem a localização rápida do arquivo.","palavraCritica":"dificulta ... mais adequado ... descritivos e padronizados","tecnica":"Nomes genéricos como 'documento1', 'teste' ou 'final' não indicam o conteúdo do arquivo, dificultando a busca e a organização, especialmente quando há muitos arquivos semelhantes. Nomes descritivos e padronizados (assunto, data, versão) facilitam a localização rápida e a organização geral.","regraMental":"Nome genérico = difícil de achar depois. Nome descritivo (assunto+data+versão) = fácil de achar."},"comentario":{"resolucao":"CERTO. Nomear arquivos com termos genéricos como 'documento1', 'teste' ou 'final' dificulta a localização e a organização no Windows, sendo mais adequado o uso de nomes descritivos e padronizados, que indiquem assunto, data e versão do arquivo.","fundamento":"Doutrina de Informática — Gestão e organização de arquivos (boas práticas de nomeação).","macete":"Nome genérico dificulta a busca; nome descritivo (assunto/data/versão) facilita.","erroComum":"Achar que nomes curtos e genéricos favorecem, e não prejudicam, a busca de arquivos.","comoBancaPensa":"Item 'limpo' sobre boas práticas de organização documental, tema recorrente em provas de informática básica."}},"TI-077":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que nomes genéricos dificultam, e não facilitam, a busca e a organização.","mede":"Informática — Gestão e organização de arquivos (boas práticas de nomeação).","pegadinhaDesc":"A banca classifica como 'eficiente' e 'padronizado' uma prática que, na realidade, é reconhecida como inadequada.","ondeErra":"Confunde nomes curtos e genéricos com nomes padronizados, tratando-os como sinônimos de boa prática.","palavraCritica":"prática eficiente ... facilitam a busca rápida","tecnica":"Nomes genéricos como 'documento1', 'teste' ou 'final' não descrevem o conteúdo do arquivo, dificultando a busca — especialmente quando há muitos arquivos com nomes semelhantes. A boa prática recomendada envolve nomes descritivos e padronizados, que indiquem assunto, data e versão.","regraMental":"Nome genérico não é padronizado — é vago. Isso dificulta, não facilita, a busca."},"comentario":{"resolucao":"ERRADO. Nomear arquivos como 'documento1', 'teste' ou 'final' é prática pouco eficiente, pois esses nomes genéricos não descrevem o conteúdo do arquivo, dificultando a busca e a organização — especialmente quando há muitos arquivos semelhantes armazenados.","fundamento":"Doutrina de Informática — Gestão e organização de arquivos (boas práticas de nomeação).","macete":"Nome genérico ≠ padronizado. Ele dificulta, não facilita, a busca.","erroComum":"Confundir simplicidade do nome com eficiência de organização.","comoBancaPensa":"Qualifica erroneamente como 'eficiente' e 'padronizado' uma prática de nomeação reconhecidamente inadequada."}},"TI-078":{"cognitivo":{"motivo":"Cobrar que o Windows compacta/descompacta ZIP nativamente, ao contrário de RAR e 7z.","mede":"Informática — Sistemas Operacionais (Windows, compactação de arquivos).","pegadinhaDesc":"A banca pode afirmar que RAR e 7z também têm suporte nativo, ou que o ZIP exige programas externos.","ondeErra":"Confunde o suporte nativo ao ZIP com os formatos RAR e 7z, que realmente exigem software adicional.","palavraCritica":"suporte nativo ... RAR e 7z ... exigem software específico","tecnica":"O Windows compacta e descompacta arquivos no formato ZIP de forma nativa, por meio da opção 'Enviar para → Pasta compactada' (ou extração direta ao abrir o arquivo). Já os formatos RAR e 7z exigem a instalação de programas adicionais, como WinRAR ou 7-Zip.","regraMental":"ZIP é nativo do Windows. RAR e 7z precisam de programa externo (WinRAR, 7-Zip)."},"comentario":{"resolucao":"CERTO. O Windows possui suporte nativo ao formato ZIP, permitindo compactar e descompactar arquivos sem programas adicionais — ao contrário dos formatos RAR e 7z, que exigem a instalação de softwares específicos, como o WinRAR e o 7-Zip.","fundamento":"Doutrina de Informática — Sistemas Operacionais (compactação de arquivos no Windows).","macete":"ZIP é nativo; RAR e 7z não são.","erroComum":"Achar que RAR e 7z também possuem suporte nativo no Windows, como o ZIP.","comoBancaPensa":"Item 'limpo' que contrasta corretamente o suporte nativo do ZIP com a dependência de software do RAR/7z."}},"TI-079":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que o Windows já compacta e descompacta ZIP nativamente, sem depender de terceiros.","mede":"Informática — Sistemas Operacionais (Windows, compactação de arquivos).","pegadinhaDesc":"A banca nega totalmente o suporte nativo do Windows à compactação, mesmo para o formato ZIP.","ondeErra":"Ignora que o ZIP é justamente o formato com suporte nativo no Windows, ao contrário de RAR e 7z.","palavraCritica":"inclusive para arquivos ZIP","tecnica":"O Windows possui suporte nativo ao formato ZIP, permitindo compactar e descompactar arquivos sem instalar nenhum programa adicional. Apenas para formatos como RAR e 7z é que a instalação de softwares de terceiros, como WinRAR e 7-Zip, é necessária.","regraMental":"ZIP sempre foi nativo do Windows — a exigência de programa é só para RAR/7z."},"comentario":{"resolucao":"ERRADO. O Windows possui suporte nativo ao formato ZIP, permitindo compactar e descompactar arquivos sem qualquer programa adicional. A exigência de softwares de terceiros, como WinRAR ou 7-Zip, aplica-se apenas a formatos como RAR e 7z — não ao ZIP.","fundamento":"Doutrina de Informática — Sistemas Operacionais (compactação de arquivos no Windows).","macete":"ZIP nunca precisou de programa de terceiros no Windows.","erroComum":"Estender a exigência de software de terceiros (válida para RAR/7z) também ao formato ZIP.","comoBancaPensa":"Generaliza indevidamente uma exigência real (RAR/7z) para um formato que já é suportado nativamente (ZIP)."}},"TI-080":{"cognitivo":{"motivo":"Cobrar que mover arquivos entre volumes diferentes faz o arquivo herdar as permissões do destino (por ser, tecnicamente, copiar+apagar).","mede":"Informática — Sistemas Operacionais (Windows, sistema de arquivos NTFS, permissões).","pegadinhaDesc":"A banca pode afirmar que as permissões originais são sempre mantidas, independentemente do volume de origem e destino.","ondeErra":"Não sabe que mover entre volumes diferentes tecnicamente equivale a copiar e apagar o original.","palavraCritica":"unidades diferentes ... herda as permissões ... copiar e apagar","tecnica":"Ao mover um arquivo entre unidades (volumes) diferentes, o Windows, tecnicamente, copia o arquivo para o destino e apaga o original — por isso, o arquivo passa a herdar as permissões NTFS da pasta de destino. Apenas quando o movimento ocorre dentro do MESMO volume é que as permissões originais são preservadas.","regraMental":"Mover entre volumes diferentes = copiar+apagar = herda permissão do destino. Mesmo volume = preserva permissão original."},"comentario":{"resolucao":"CERTO. Ao mover um arquivo entre unidades (volumes) diferentes, a operação equivale, tecnicamente, a copiar o arquivo para o destino e apagar o original — por isso, o arquivo passa a herdar as permissões NTFS da pasta de destino, e não mantém as permissões originais.","fundamento":"Doutrina de Informática — Sistemas Operacionais (Windows, sistema de arquivos NTFS).","macete":"Unidades diferentes: mover = copiar + apagar → herda permissão do destino.","erroComum":"Achar que as permissões NTFS originais são sempre preservadas, independentemente do volume.","comoBancaPensa":"Item 'limpo' que explica corretamente a exceção técnica (mover entre volumes = copiar+apagar) que gera a herança de permissões."}},"TI-081":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que mover entre volumes diferentes NÃO preserva as permissões originais (o arquivo herda as do destino).","mede":"Informática — Sistemas Operacionais (Windows, sistema de arquivos NTFS, permissões).","pegadinhaDesc":"A banca generaliza indevidamente a preservação de permissões para qualquer situação de movimentação de arquivos.","ondeErra":"Ignora a distinção entre mover dentro do mesmo volume (preserva permissões) e mover entre volumes diferentes (herda as do destino).","palavraCritica":"mantém integralmente ... independentemente do volume","tecnica":"Apenas quando o arquivo é movido DENTRO do mesmo volume as permissões NTFS originais são preservadas. Ao mover entre volumes (unidades) diferentes, a operação equivale, tecnicamente, a copiar e apagar o original, fazendo o arquivo herdar as permissões da pasta de destino.","regraMental":"Mesmo volume: preserva permissão. Volumes diferentes: herda permissão do destino. Nunca é 'sempre igual'."},"comentario":{"resolucao":"ERRADO. Ao mover um arquivo entre unidades (volumes) diferentes, o arquivo NÃO mantém suas permissões NTFS originais — ele passa a herdar as permissões da pasta de destino, já que essa operação equivale, tecnicamente, a copiar o arquivo e apagar o original. A preservação das permissões só ocorre quando o movimento é feito dentro do mesmo volume.","fundamento":"Doutrina de Informática — Sistemas Operacionais (Windows, sistema de arquivos NTFS).","macete":"'Independentemente do volume' é a palavra-chave do erro: o volume, na verdade, faz toda a diferença.","erroComum":"Generalizar a preservação de permissões para qualquer cenário de movimentação de arquivos.","comoBancaPensa":"Generaliza indevidamente uma regra que só vale para um caso específico (mesmo volume) para todos os casos."}},"TI-082":{"cognitivo":{"motivo":"Cobrar que a navegação anônima só oferece privacidade local, sem ocultar a atividade perante sites e provedores.","mede":"Informática — Internet (navegação anônima/privada).","pegadinhaDesc":"A banca pode afirmar que a aba anônima também esconde a atividade de sites e do provedor de Internet.","ondeErra":"Confunde 'não salvar histórico no dispositivo' com 'anonimato completo perante terceiros na rede'.","palavraCritica":"não impede ... identifiquem","tecnica":"A aba anônima/privada oferece privacidade apenas local: não grava histórico, cookies nem cache no aparelho usado. Ela não esconde a atividade do usuário de sites visitados, do provedor de Internet ou da rede — anônimo não é sinônimo de anonimato completo na Internet.","regraMental":"Aba anônima: privacidade só local. Sites e provedor continuam vendo tudo."},"comentario":{"resolucao":"CERTO. A navegação em abas anônimas/privadas evita apenas que o navegador salve, no dispositivo local, o histórico, os cookies e o cache da sessão — mas não impede que sites visitados e o provedor de Internet identifiquem as atividades do usuário.","fundamento":"Doutrina de Informática — Internet (navegação anônima/privada).","macete":"Anônimo ≠ anonimato na Internet: só esconde do dispositivo, não da rede.","erroComum":"Achar que a aba anônima torna o usuário invisível para sites e provedores.","comoBancaPensa":"Item 'limpo' que corrige a crença popular equivocada sobre o alcance da navegação privada."}},"TI-083":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a navegação anônima não impede o rastreamento por sites e provedores.","mede":"Informática — Internet (navegação anônima/privada).","pegadinhaDesc":"A banca amplia o alcance da privacidade local para um suposto anonimato completo na rede.","ondeErra":"Acredita que a ausência de histórico local implica invisibilidade perante toda a Internet.","palavraCritica":"completamente irrastreável ... impede que sites ... identifiquem","tecnica":"A navegação anônima/privada apenas evita o registro local de histórico, cookies e cache. Sites visitados e o provedor de Internet continuam podendo identificar a atividade do usuário — o modo anônimo não garante anonimato completo na rede.","regraMental":"Privacidade local ≠ invisibilidade na rede. Sites e provedor sempre veem a atividade."},"comentario":{"resolucao":"ERRADO. A navegação em abas anônimas/privadas não torna o usuário irrastreável na Internet — ela apenas evita o registro local de histórico, cookies e cache. Sites visitados e o provedor de Internet continuam podendo identificar as atividades realizadas.","fundamento":"Doutrina de Informática — Internet (navegação anônima/privada).","macete":"Anônimo é só localmente — nunca é 'completo' perante sites e provedor.","erroComum":"Tratar a privacidade local da aba anônima como sinônimo de anonimato irrestrito.","comoBancaPensa":"Usa 'completamente irrastreável' para generalizar indevidamente uma proteção que é apenas local."}},"TI-084":{"cognitivo":{"motivo":"Cobrar que, apesar da infraestrutura compartilhada, os dados de cada organização permanecem isolados na nuvem pública.","mede":"Informática — Internet e Computação em nuvem (nuvem pública, multi-inquilino).","pegadinhaDesc":"A banca pode afirmar que outras organizações conseguem visualizar (mesmo sem alterar) os dados de terceiros.","ondeErra":"Confunde 'infraestrutura pública/compartilhada' com 'dados visíveis a outros clientes'.","palavraCritica":"não podendo ser visualizados nem alterados","tecnica":"A nuvem pública utiliza um modelo multi-inquilino (multitenant): a infraestrutura física é compartilhada entre clientes, mas cada um é logicamente isolado dos demais — o termo 'pública' refere-se à infraestrutura compartilhada, e não à exposição dos dados armazenados.","regraMental":"Nuvem pública: infra compartilhada, dados isolados. 'Pública' é a infra, não os dados."},"comentario":{"resolucao":"CERTO. Na nuvem pública, apesar de a infraestrutura física ser compartilhada entre organizações (modelo multi-inquilino), os dados de cada cliente permanecem isolados, não podendo ser visualizados nem alterados por outras organizações que utilizam o mesmo provedor.","fundamento":"Doutrina de Informática — Computação em nuvem (nuvem pública, isolamento multi-inquilino).","macete":"'Pública' é a infraestrutura compartilhada; os dados de cada cliente são isolados.","erroComum":"Achar que 'nuvem pública' significa que os dados armazenados também são públicos ou visíveis a terceiros.","comoBancaPensa":"Item 'limpo' que esclarece a distinção entre infraestrutura compartilhada e isolamento lógico de dados."}},"TI-085":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que o caráter público da nuvem se refere à infraestrutura, e não à visibilidade dos dados dos clientes.","mede":"Informática — Internet e Computação em nuvem (nuvem pública, multi-inquilino).","pegadinhaDesc":"A banca estende indevidamente o adjetivo 'pública' da infraestrutura para os dados armazenados.","ondeErra":"Assume que 'nuvem pública' implica dados acessíveis a qualquer organização que compartilhe o provedor.","palavraCritica":"se estende também à visibilidade dos dados","tecnica":"O termo 'nuvem pública' refere-se ao compartilhamento da infraestrutura física entre múltiplos clientes (modelo multi-inquilino), e não à exposição dos dados. Cada organização permanece isolada das demais, sem que outros clientes do mesmo provedor possam visualizar ou alterar seus dados.","regraMental":"'Público' descreve a infraestrutura, nunca os dados — que ficam isolados por cliente."},"comentario":{"resolucao":"ERRADO. Os dados de uma organização armazenados em nuvem pública NÃO podem ser visualizados por outras organizações que utilizam o mesmo provedor — o caráter 'público' refere-se à infraestrutura física compartilhada (modelo multi-inquilino), e não à visibilidade dos dados, que permanecem isolados por cliente.","fundamento":"Doutrina de Informática — Computação em nuvem (nuvem pública, isolamento multi-inquilino).","macete":"Nunca confundir 'infraestrutura pública' com 'dados públicos'.","erroComum":"Estender o adjetivo 'pública' da infraestrutura para a visibilidade dos dados armazenados.","comoBancaPensa":"Parte de uma premissa parcialmente correta (dados não alteráveis por terceiros) para inserir uma conclusão falsa (dados visíveis por terceiros)."}},"TI-086":{"cognitivo":{"motivo":"Cobrar a definição correta e completa de computação em nuvem, incluindo o provisionamento sob demanda.","mede":"Informática — Internet e Computação em nuvem (conceito).","pegadinhaDesc":"A banca pode negar a elasticidade/escalabilidade dinâmica do modelo de nuvem.","ondeErra":"Acha que a computação em nuvem ainda exige dimensionamento fixo e investimento prévio em infraestrutura própria.","palavraCritica":"sem a necessidade de investimento prévio ... dimensionada para o pico de uso","tecnica":"A computação em nuvem permite acesso remoto a recursos compartilhados (servidores, armazenamento, aplicações) de forma dinâmica e escalável, geralmente via Internet. O provisionamento sob demanda dispensa o investimento prévio em infraestrutura própria dimensionada para o pico de uso, sendo uma de suas principais vantagens econômicas.","regraMental":"Nuvem = acesso remoto, dinâmico, escalável, sob demanda — sem precisar comprar infra própria."},"comentario":{"resolucao":"CERTO. A computação em nuvem é um estilo de computação que permite acesso remoto a recursos compartilhados de forma dinâmica e escalável, geralmente via Internet, possibilitando o provisionamento sob demanda sem investimento prévio em infraestrutura própria dimensionada para o pico de uso.","fundamento":"Doutrina de Informática — Computação em nuvem (conceito e características).","macete":"Nuvem: remoto + compartilhado + dinâmico + escalável + sob demanda.","erroComum":"Achar que a nuvem ainda exige infraestrutura própria dimensionada previamente.","comoBancaPensa":"Item 'limpo' que reúne as características centrais do conceito de computação em nuvem."}},"TI-087":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a elasticidade/escalabilidade dinâmica é característica central da computação em nuvem.","mede":"Informática — Internet e Computação em nuvem (conceito).","pegadinhaDesc":"A banca nega justamente a característica que diferencia a nuvem da infraestrutura local tradicional.","ondeErra":"Confunde o modelo de nuvem (elástico, sob demanda) com o modelo tradicional de infraestrutura própria (fixo, dimensionado previamente).","palavraCritica":"não permite ... quantidade fixa ... semelhante à infraestrutura local","tecnica":"Uma das principais características da computação em nuvem é justamente permitir o provisionamento dinâmico e escalável de recursos, sob demanda, dispensando a necessidade de dimensionamento fixo prévio — ao contrário da infraestrutura local tradicional, que de fato exige esse planejamento antecipado.","regraMental":"Nuvem é o oposto do dimensionamento fixo: ela é elástica e sob demanda."},"comentario":{"resolucao":"ERRADO. A computação em nuvem permite justamente o dimensionamento dinâmico e escalável de recursos sob demanda, dispensando a contratação prévia de uma capacidade fixa dimensionada para o pico de uso — essa é uma das principais vantagens da nuvem em relação à infraestrutura local tradicional.","fundamento":"Doutrina de Informática — Computação em nuvem (conceito e características).","macete":"Nuvem = elástica e sob demanda. Infraestrutura fixa é o modelo tradicional, não o de nuvem.","erroComum":"Inverter as características da nuvem com as da infraestrutura local tradicional.","comoBancaPensa":"Nega a elasticidade da nuvem, atribuindo-lhe as limitações do modelo tradicional de infraestrutura própria."}},"TI-088":{"cognitivo":{"motivo":"Cobrar que a intranet usa a mesma tecnologia da Internet, mas com acesso restrito à organização.","mede":"Informática — Internet e navegação (intranet e extranet).","pegadinhaDesc":"A banca pode afirmar que a intranet usa protocolos proprietários, distintos dos da Internet.","ondeErra":"Acha que, por ser restrita, a intranet precisa de tecnologia/protocolos diferentes dos usados na Internet.","palavraCritica":"mesmos protocolos ... rede mais restrita","tecnica":"A intranet emprega os mesmos protocolos da Internet (TCP/IP, HTTP, entre outros), mas é uma rede restrita, de acesso limitado aos usuários de uma organização. Quando esse acesso é estendido a parceiros externos, de forma controlada, tem-se uma extranet.","regraMental":"Intranet: mesma tecnologia da Internet, mas de uso interno e restrito."},"comentario":{"resolucao":"CERTO. A intranet utiliza os mesmos protocolos empregados na Internet (como TCP/IP e HTTP), mas constitui uma rede mais restrita, de acesso limitado aos usuários autorizados dentro de uma organização.","fundamento":"Doutrina de Informática — Internet e navegação (intranet e extranet).","macete":"Intranet = mesma tecnologia da Internet, uso interno e restrito.","erroComum":"Achar que a intranet usa protocolos próprios, diferentes dos da Internet.","comoBancaPensa":"Item 'limpo' sobre a definição correta de intranet e sua relação tecnológica com a Internet."}},"TI-089":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a intranet usa os mesmos protocolos da Internet, e não protocolos proprietários.","mede":"Informática — Internet e navegação (intranet e extranet).","pegadinhaDesc":"A banca associa a restrição de acesso da intranet a uma suposta incompatibilidade tecnológica com a Internet.","ondeErra":"Confunde 'acesso restrito' com 'tecnologia proprietária e incompatível'.","palavraCritica":"protocolos ... proprietários e incompatíveis","tecnica":"A intranet utiliza exatamente os mesmos protocolos empregados na Internet, como TCP/IP e HTTP — a diferença está apenas no escopo de acesso, restrito aos usuários autorizados da organização, e não na tecnologia de rede utilizada.","regraMental":"Intranet nunca usa protocolo proprietário — a restrição é de acesso, não de tecnologia."},"comentario":{"resolucao":"ERRADO. A intranet utiliza os mesmos protocolos empregados na Internet, como TCP/IP e HTTP, e não protocolos proprietários ou incompatíveis. A restrição da intranet está no escopo de acesso (limitado à organização), e não na tecnologia de comunicação utilizada.","fundamento":"Doutrina de Informática — Internet e navegação (intranet e extranet).","macete":"Restrição de acesso ≠ tecnologia diferente. Intranet usa TCP/IP e HTTP, como a Internet.","erroComum":"Achar que uma rede restrita precisa, necessariamente, de protocolos próprios e incompatíveis.","comoBancaPensa":"Associa indevidamente a restrição de acesso da intranet a uma incompatibilidade tecnológica inexistente."}},"TI-090":{"cognitivo":{"motivo":"Cobrar a distinção correta entre PaaS (plataforma para o cliente desenvolver aplicações) e SaaS (software pronto para uso).","mede":"Informática — Computação em nuvem (modelos de serviço: SaaS, PaaS, IaaS).","pegadinhaDesc":"A banca pode chamar de SaaS o modelo em que o cliente desenvolve suas próprias aplicações (que é, na verdade, PaaS).","ondeErra":"Confunde PaaS (plataforma de desenvolvimento) com SaaS (software pronto para uso final).","palavraCritica":"PaaS ... desenvolva e gerencie ... SaaS ... software já pronto","tecnica":"No PaaS (Platform as a Service), o provedor oferece infraestrutura e ferramentas de desenvolvimento, cabendo ao cliente criar e gerenciar suas próprias aplicações. Já no SaaS (Software as a Service), o cliente apenas utiliza um software já pronto, como Gmail ou Office 365, sem desenvolvê-lo.","regraMental":"PaaS: cliente desenvolve apps na plataforma fornecida. SaaS: cliente só usa o software pronto."},"comentario":{"resolucao":"CERTO. No PaaS (plataforma como serviço), o provedor disponibiliza infraestrutura e ferramentas de desenvolvimento para que o cliente desenvolva e gerencie suas próprias aplicações — diferentemente do SaaS, em que o cliente apenas utiliza um software já pronto fornecido pelo provedor.","fundamento":"Doutrina de Informática — Computação em nuvem (SaaS x PaaS x IaaS).","macete":"Cliente desenvolve apps = PaaS. Cliente só usa app pronto = SaaS.","erroComum":"Chamar de SaaS um modelo em que o cliente efetivamente desenvolve suas próprias aplicações.","comoBancaPensa":"Item 'limpo' que contrasta corretamente PaaS e SaaS, evitando a troca de rótulos entre os modelos."}},"TI-091":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a descrição de 'infraestrutura e ferramentas para o cliente desenvolver aplicações' corresponde ao PaaS, e não ao SaaS.","mede":"Informática — Computação em nuvem (modelos de serviço: SaaS, PaaS, IaaS).","pegadinhaDesc":"A banca rotula como SaaS uma descrição que, na verdade, corresponde ao modelo PaaS.","ondeErra":"Não percebe que 'desenvolver e gerenciar suas próprias aplicações' é a marca do PaaS, e não do SaaS.","palavraCritica":"software como serviço (SaaS) ... desenvolver e gerenciar suas próprias aplicações","tecnica":"A descrição apresentada — infraestrutura e ferramentas de desenvolvimento para o cliente criar e gerenciar suas próprias aplicações — corresponde ao modelo PaaS (Platform as a Service), e não ao SaaS. No SaaS, o cliente apenas utiliza um software já pronto, sem desenvolvê-lo.","regraMental":"'Cliente desenvolve aplicação' nunca é SaaS — é sempre PaaS."},"comentario":{"resolucao":"ERRADO. A descrição apresentada — provedor oferece infraestrutura e ferramentas para o cliente desenvolver e gerenciar suas próprias aplicações — corresponde ao modelo PaaS (Platform as a Service), e não ao SaaS. No SaaS, o cliente apenas utiliza um software já pronto, fornecido pelo provedor.","fundamento":"Doutrina de Informática — Computação em nuvem (SaaS x PaaS x IaaS).","macete":"Desenvolver app = PaaS. Usar app pronto = SaaS. Nunca inverter.","erroComum":"Rotular como SaaS uma descrição que corresponde tecnicamente ao modelo PaaS.","comoBancaPensa":"Troca o rótulo do modelo de serviço (PaaS → SaaS), mantendo a descrição técnica correta do PaaS."}},"TI-092":{"cognitivo":{"motivo":"Cobrar as vantagens do armazenamento em nuvem e sua dependência de conexão à Internet e do provedor.","mede":"Informática — Computação em nuvem (armazenamento em nuvem).","pegadinhaDesc":"A banca pode omitir a dependência de Internet/provedor, tratando a nuvem como sempre disponível.","ondeErra":"Ignora que o acesso ao armazenamento em nuvem depende de conexão à Internet e da disponibilidade do provedor.","palavraCritica":"depende da conexão à Internet e da infraestrutura do provedor","tecnica":"O armazenamento em nuvem (cloud storage) permite salvar arquivos, bancos de dados e outras informações em servidores remotos, com vantagens de acessibilidade (de qualquer lugar) e escalabilidade (aumento sob demanda) em relação ao armazenamento local — mas depende de conexão à Internet e da infraestrutura do provedor contratado.","regraMental":"Nuvem: acessível e escalável, mas sempre dependente de Internet e do provedor."},"comentario":{"resolucao":"CERTO. O armazenamento em nuvem permite salvar arquivos, bancos de dados e outras informações em servidores remotos, com vantagens de acessibilidade e escalabilidade frente ao armazenamento local — ainda que sua disponibilidade dependa da conexão à Internet e da infraestrutura do provedor contratado.","fundamento":"Doutrina de Informática — Computação em nuvem (armazenamento em nuvem).","macete":"Nuvem: acessibilidade + escalabilidade, mas sempre com dependência de Internet/provedor.","erroComum":"Tratar o armazenamento em nuvem como isento de qualquer dependência externa.","comoBancaPensa":"Item 'limpo' que soma as vantagens do cloud storage com sua limitação inerente (dependência de conexão)."}},"TI-093":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que o armazenamento em nuvem depende de conexão à Internet para ser acessado.","mede":"Informática — Computação em nuvem (armazenamento em nuvem).","pegadinhaDesc":"A banca afirma que os arquivos na nuvem continuam acessíveis mesmo sem qualquer conectividade.","ondeErra":"Ignora que o acesso a arquivos armazenados em servidores remotos exige conexão à Internet.","palavraCritica":"totalmente independentes ... ausência completa de conectividade","tecnica":"O armazenamento em nuvem depende, por definição, de conexão à Internet para que o usuário acesse os arquivos salvos em servidores remotos. Na ausência completa de conectividade, o acesso a esses arquivos fica impossibilitado (salvo cópias sincronizadas localmente, quando disponíveis).","regraMental":"Nuvem sem Internet = sem acesso. Não existe cloud storage 'independente de conexão'."},"comentario":{"resolucao":"ERRADO. O armazenamento em nuvem depende de conexão à Internet para que os arquivos armazenados em servidores remotos sejam acessados — na ausência completa de conectividade, o acesso a esses arquivos fica impossibilitado, ao contrário do que afirma o item.","fundamento":"Doutrina de Informática — Computação em nuvem (armazenamento em nuvem).","macete":"Nuvem sempre depende de Internet — nunca é 'totalmente independente' de conexão.","erroComum":"Achar que arquivos em nuvem continuam acessíveis mesmo sem qualquer conectividade de rede.","comoBancaPensa":"Usa 'totalmente independentes' para transformar uma dependência real (conexão à Internet) em algo inexistente."}},"TI-094":{"cognitivo":{"motivo":"Cobrar que, no SaaS, é o provedor (e não o cliente) quem controla a infraestrutura e mantém as aplicações.","mede":"Informática — Computação em nuvem (SaaS, responsabilidade do provedor).","pegadinhaDesc":"A banca pode inverter a responsabilidade, atribuindo ao cliente o controle da infraestrutura no SaaS.","ondeErra":"Confunde as responsabilidades do cliente e do provedor no modelo SaaS.","palavraCritica":"provedor detém o controle ... responsável pela instalação, configuração e manutenção","tecnica":"No SaaS, o provedor é responsável pela infraestrutura de rede, servidores, sistema operacional e pela instalação, configuração e manutenção das aplicações. O cliente apenas utiliza o software e seus dados, sem gerenciar nenhuma camada de infraestrutura subjacente.","regraMental":"SaaS: provedor cuida de tudo (infra + SO + app). Cliente só usa."},"comentario":{"resolucao":"CERTO. No modelo SaaS, o provedor detém o controle sobre a infraestrutura de rede, os servidores e o sistema operacional, sendo responsável pela instalação, configuração e manutenção das aplicações — cabendo ao cliente apenas utilizar o software disponibilizado.","fundamento":"Doutrina de Informática — Computação em nuvem (SaaS, responsabilidade do provedor).","macete":"SaaS: provedor controla infra/SO/app. Cliente só usa.","erroComum":"Atribuir ao cliente, e não ao provedor, o controle da infraestrutura no modelo SaaS.","comoBancaPensa":"Item 'limpo' que descreve corretamente a divisão de responsabilidades no modelo SaaS."}},"TI-095":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que é o provedor — e não o consumidor — quem controla a infraestrutura no modelo SaaS.","mede":"Informática — Computação em nuvem (SaaS, responsabilidade do provedor).","pegadinhaDesc":"A banca inverte o sujeito responsável pela infraestrutura, atribuindo ao consumidor uma tarefa do provedor.","ondeErra":"Troca as responsabilidades: acha que, no SaaS, é o cliente quem cuida de infraestrutura e manutenção.","palavraCritica":"consumidor tem controle ... responsável pela instalação","tecnica":"No SaaS, é o provedor — e não o consumidor — quem detém o controle sobre a infraestrutura de rede, os servidores e o sistema operacional, sendo responsável pela instalação, configuração e manutenção das aplicações. O consumidor apenas utiliza o software e seus dados.","regraMental":"No SaaS, quem cuida da infra é o provedor, nunca o consumidor."},"comentario":{"resolucao":"ERRADO. No modelo SaaS, é o provedor — e não o consumidor — quem detém o controle sobre a infraestrutura de rede, os servidores e o sistema operacional, sendo responsável pela instalação, configuração e manutenção das aplicações. O consumidor apenas utiliza o software fornecido.","fundamento":"Doutrina de Informática — Computação em nuvem (SaaS, responsabilidade do provedor).","macete":"SaaS: cliente nunca controla infra/SO — quem controla é sempre o provedor.","erroComum":"Inverter o sujeito responsável pela infraestrutura no modelo SaaS.","comoBancaPensa":"Troca o sujeito da assertiva (provedor → consumidor) mantendo a descrição técnica da infraestrutura."}},"TI-096":{"cognitivo":{"motivo":"Cobrar que ferramentas de acesso remoto permitem transferência de arquivos e que as suítes de escritório oferecem compatibilidade entre formatos.","mede":"Informática — Ferramentas de produtividade e acesso remoto.","pegadinhaDesc":"A banca pode negar a possibilidade de transferência de arquivos nesses aplicativos de acesso remoto, ou negar a compatibilidade entre formatos das suítes.","ondeErra":"Acha que ferramentas como TeamViewer só permitem visualizar a tela remota, sem transferir arquivos.","palavraCritica":"transferência de arquivos ... compatibilidade entre diversos formatos","tecnica":"O Microsoft Remote Desktop e o TeamViewer permitem tanto o controle remoto de um computador quanto a transferência de arquivos entre as máquinas conectadas. Já o Microsoft Office e o LibreOffice, por sua vez, oferecem compatibilidade entre diversos formatos de arquivo (por exemplo, .docx e .odt).","regraMental":"Remote Desktop/TeamViewer: controle remoto + transferir arquivo. Office/LibreOffice: compatíveis entre si."},"comentario":{"resolucao":"CERTO. O Microsoft Remote Desktop e o TeamViewer permitem acesso remoto a computadores, possibilitando a transferência de arquivos entre as máquinas conectadas, enquanto o Microsoft Office e o LibreOffice oferecem compatibilidade entre diversos formatos de documentos, planilhas e apresentações.","fundamento":"Doutrina de Informática — Ferramentas de produtividade e acesso remoto.","macete":"Acesso remoto moderno sempre permite transferir arquivo; Office e LibreOffice são compatíveis entre si.","erroComum":"Achar que ferramentas de acesso remoto só permitem visualização, sem transferência de arquivos.","comoBancaPensa":"Item 'limpo' que combina dois fatos corretos sobre ferramentas de produtividade amplamente usadas."}},"TI-097":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que ferramentas de acesso remoto permitem transferência de arquivos e que Office/LibreOffice mantêm compatibilidade entre formatos.","mede":"Informática — Ferramentas de produtividade e acesso remoto.","pegadinhaDesc":"A banca nega dois fatos corretos simultaneamente: a transferência de arquivos e a compatibilidade entre suítes.","ondeErra":"Acha que ferramentas de acesso remoto se limitam à visualização de tela e que Office e LibreOffice não têm nenhuma compatibilidade.","palavraCritica":"apenas a visualização ... totalmente incompatíveis","tecnica":"O Microsoft Remote Desktop e o TeamViewer permitem, além da visualização, a transferência de arquivos entre as máquinas conectadas. Já o Microsoft Office e o LibreOffice mantêm compatibilidade entre diversos formatos de arquivo (como .docx e .odt), não sendo totalmente incompatíveis entre si.","regraMental":"Acesso remoto moderno sempre transfere arquivo; Office e LibreOffice sempre têm compatibilidade parcial/total entre formatos."},"comentario":{"resolucao":"ERRADO. Ferramentas como o Microsoft Remote Desktop e o TeamViewer permitem, sim, a transferência de arquivos entre as máquinas conectadas, além da visualização remota. E o Microsoft Office e o LibreOffice mantêm compatibilidade entre diversos formatos de arquivo, não sendo totalmente incompatíveis entre si.","fundamento":"Doutrina de Informática — Ferramentas de produtividade e acesso remoto.","macete":"Nunca negar transferência de arquivo em acesso remoto moderno, nem compatibilidade entre Office/LibreOffice.","erroComum":"Achar que ferramentas de acesso remoto só exibem a tela e que suítes de escritório distintas são sempre incompatíveis.","comoBancaPensa":"Combina duas negações absolutas ('apenas', 'totalmente incompatíveis') para criar um item duplamente falso."}},"TI-098":{"cognitivo":{"motivo":"Cobrar que a impressão em rede deixa registros recuperáveis, úteis em auditoria e perícia.","mede":"Informática — Ferramentas de produtividade (impressão em rede, rastros digitais).","pegadinhaDesc":"A banca pode negar a possibilidade de recuperação desses dados após a impressão.","ondeErra":"Acha que, uma vez impresso o documento, nenhuma informação sobre a impressão pode ser recuperada.","palavraCritica":"resgatar informações ... usuário ... data ... nome do arquivo ... quantidade de folhas","tecnica":"Ao imprimir documentos em uma impressora de rede, o servidor de impressão (spooler) registra informações como o usuário solicitante, a data e hora, o nome do arquivo impresso e a quantidade de folhas — dados que podem ser recuperados posteriormente e são úteis em auditorias e perícias forenses.","regraMental":"Impressão em rede deixa rastro: usuário, data, arquivo, nº de folhas — tudo fica registrado."},"comentario":{"resolucao":"CERTO. Quando documentos são impressos em uma impressora de rede, é possível, por meio dos registros do servidor de impressão (spooler), resgatar informações como o usuário solicitante, a data da impressão, o nome do arquivo e a quantidade de folhas impressas — dados úteis, inclusive, em investigações periciais.","fundamento":"Doutrina de Informática — Ferramentas de produtividade (impressão em rede, rastros digitais).","macete":"Impressora de rede = spooler registra tudo: quem, quando, o quê e quantas páginas.","erroComum":"Achar que não é possível recuperar nenhuma informação sobre uma impressão já realizada.","comoBancaPensa":"Item 'limpo' sobre um tema de interesse direto para carreiras policiais (rastros digitais e perícia)."}},"TI-099":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a impressão em rede deixa registros recuperáveis pelo servidor de impressão.","mede":"Informática — Ferramentas de produtividade (impressão em rede, rastros digitais).","pegadinhaDesc":"A banca nega totalmente a existência de registros de impressão, o que é falso.","ondeErra":"Ignora que o servidor de impressão (spooler) registra usuário, data, arquivo e quantidade de páginas.","palavraCritica":"não deixam qualquer tipo de registro ... impossível","tecnica":"Os registros do servidor de impressão (spooler) armazenam informações como o usuário solicitante, a data, o nome do arquivo impresso e a quantidade de folhas — dados que podem, sim, ser recuperados após a impressão e utilizados em investigações periciais.","regraMental":"Impressão de rede sempre deixa rastro no spooler — nunca é 'impossível' recuperar."},"comentario":{"resolucao":"ERRADO. Documentos impressos em uma impressora de rede deixam, sim, registros recuperáveis no servidor de impressão (spooler) — incluindo usuário solicitante, data, nome do arquivo e quantidade de folhas —, dados que podem ser utilizados em investigações periciais.","fundamento":"Doutrina de Informática — Ferramentas de produtividade (impressão em rede, rastros digitais).","macete":"Nunca é 'impossível' recuperar dados de impressão em rede — o spooler sempre registra.","erroComum":"Achar que a impressão não deixa nenhum vestígio recuperável após sua conclusão.","comoBancaPensa":"Usa termos absolutos ('não deixam qualquer', 'impossível') para negar um fato tecnicamente verificável."}},"TI-100":{"cognitivo":{"motivo":"Cobrar que a pesquisa aprimorada do Google pode depender de dados estruturados (schema) das páginas indexadas.","mede":"Informática — Mecanismos de busca (pesquisa aprimorada, dados estruturados).","pegadinhaDesc":"A banca pode negar que resultados de busca dependam de dados estruturados/marcações da página.","ondeErra":"Acha que o resultado de busca depende exclusivamente do texto simples da página, ignorando marcações estruturadas.","palavraCritica":"dados estruturados (marcações do tipo schema)","tecnica":"A pesquisa aprimorada do Google pode apresentar resultados ricos (rich results) — como avaliações, preços ou eventos — que dependem de dados estruturados (marcações schema) presentes nas páginas indexadas, ajudando o mecanismo de busca a organizar e exibir informações adicionais sobre o conteúdo.","regraMental":"Resultados ricos do Google dependem de dados estruturados (schema) na página."},"comentario":{"resolucao":"CERTO. A pesquisa aprimorada do Google pode apresentar resultados ricos que dependem de dados estruturados (marcações do tipo schema) presentes nas páginas indexadas, os quais ajudam o mecanismo de busca a organizar e exibir informações adicionais sobre o conteúdo encontrado.","fundamento":"Doutrina de Informática — Mecanismos de busca (pesquisa aprimorada, dados estruturados).","macete":"Resultados ricos = dados estruturados (schema) na página indexada.","erroComum":"Achar que os resultados de busca dependem apenas do texto puro, sem qualquer marcação estruturada.","comoBancaPensa":"Item 'limpo' sobre um recurso técnico de SEO/busca pouco conhecido, mas relevante."}},"TI-101":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a pesquisa aprimorada do Google pode depender de dados estruturados (schema) da página.","mede":"Informática — Mecanismos de busca (pesquisa aprimorada, dados estruturados).","pegadinhaDesc":"A banca nega totalmente o papel dos dados estruturados na exibição de resultados de busca.","ondeErra":"Ignora que marcações estruturadas (schema) influenciam a exibição de resultados ricos pelo Google.","palavraCritica":"independem de qualquer marcação ... exclusivamente o texto simples","tecnica":"A pesquisa aprimorada do Google pode apresentar resultados ricos que dependem justamente de dados estruturados (marcações schema) presentes nas páginas indexadas — o mecanismo de busca não se limita ao texto simples do conteúdo.","regraMental":"Google usa dados estruturados, sim — nunca é 'exclusivamente texto simples'."},"comentario":{"resolucao":"ERRADO. A pesquisa aprimorada do Google pode apresentar resultados ricos que dependem de dados estruturados (marcações do tipo schema) presentes nas páginas indexadas — o mecanismo de busca não considera exclusivamente o texto simples do conteúdo.","fundamento":"Doutrina de Informática — Mecanismos de busca (pesquisa aprimorada, dados estruturados).","macete":"Nunca é 'exclusivamente texto simples' — dados estruturados (schema) importam para o Google.","erroComum":"Achar que marcações estruturadas nas páginas não influenciam em nada os resultados de busca.","comoBancaPensa":"Nega totalmente um mecanismo técnico real (dados estruturados) para induzir o erro."}},"TI-102":{"cognitivo":{"motivo":"Cobrar que as aspas duplas restringem à sequência exata de palavras, mas o mecanismo ainda ignora pontuação e capitalização.","mede":"Informática — Mecanismos de busca (operadores de pesquisa, aspas duplas).","pegadinhaDesc":"A banca pode afirmar que as aspas exigem também a mesma pontuação e capitalização do termo original.","ondeErra":"Acha que 'sequência exata de palavras' implica exigir também a mesma pontuação e maiúsculas/minúsculas.","palavraCritica":"geralmente ignore ... capitalização ... pontuação","tecnica":"As aspas duplas em mecanismos de busca como o Google restringem os resultados a páginas com a sequência exata das palavras delimitadas, mas o mecanismo geralmente ignora diferenças de capitalização e a maior parte da pontuação presentes na consulta original — o operador não exige correspondência literal caractere a caractere.","regraMental":"Aspas = ordem exata das palavras. Mas maiúscula/minúscula e pontuação continuam sendo ignoradas."},"comentario":{"resolucao":"CERTO. Ao delimitar uma frase entre aspas duplas, o mecanismo de busca restringe os resultados à sequência exata de palavras, mas geralmente ignora diferenças de capitalização e a maior parte da pontuação presentes nos termos da consulta original.","fundamento":"Doutrina de Informática — Mecanismos de busca (operadores de pesquisa, aspas duplas).","macete":"Aspas = ordem exata das palavras, não exige mesma pontuação/capitalização.","erroComum":"Achar que aspas duplas exigem correspondência exata de pontuação e maiúsculas/minúsculas.","comoBancaPensa":"Item 'limpo' que separa corretamente o que as aspas garantem (ordem das palavras) do que elas não garantem (pontuação/capitalização)."}},"TI-103":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que o mecanismo de busca ignora pontuação e capitalização mesmo com o uso de aspas duplas.","mede":"Informática — Mecanismos de busca (operadores de pesquisa, aspas duplas).","pegadinhaDesc":"A banca estende indevidamente a exigência de 'sequência exata de palavras' também à pontuação e capitalização.","ondeErra":"Generaliza a precisão do operador de aspas para elementos (pontuação, maiúsculas/minúsculas) que o mecanismo efetivamente ignora.","palavraCritica":"incluindo-se a mesma pontuação e capitalização","tecnica":"As aspas duplas restringem a busca à sequência exata das palavras da frase, mas o mecanismo de busca geralmente ignora diferenças de pontuação e de capitalização (maiúsculas/minúsculas) presentes nos termos originais — a exigência de correspondência exata não se estende a esses dois elementos.","regraMental":"Aspas garantem a ordem das palavras — nunca a pontuação e a capitalização idênticas."},"comentario":{"resolucao":"ERRADO. As aspas duplas restringem os resultados à sequência exata das palavras da frase pesquisada, mas o mecanismo de busca geralmente ignora a pontuação e a capitalização (maiúsculas/minúsculas) dos termos originais — ao contrário do que afirma o item.","fundamento":"Doutrina de Informática — Mecanismos de busca (operadores de pesquisa, aspas duplas).","macete":"O erro está em exigir 'mesma pontuação e capitalização' — isso o operador de aspas não garante.","erroComum":"Estender a precisão das aspas duplas (ordem das palavras) também à pontuação e à capitalização.","comoBancaPensa":"Generaliza indevidamente a exatidão do operador de busca para aspectos que ele não abrange."}},"TI-104":{"cognitivo":{"motivo":"Cobrar a distinção correta entre endereço IP (lógico), DNS (nome→IP) e ARP (IP→MAC).","mede":"Informática — Internet e Redes (endereço IP, DNS, ARP).","pegadinhaDesc":"A banca pode atribuir ao próprio endereço IP a função de 'converter' nomes de domínio, confundindo-o com o DNS.","ondeErra":"Confunde o endereço IP (um identificador lógico) com o protocolo DNS (responsável pela conversão de nomes).","palavraCritica":"endereço lógico ... DNS ... ARP","tecnica":"O endereço IP é um endereço lógico que identifica um dispositivo em uma rede. A conversão de nomes de domínio (como 'exemplo.com') em endereços IP é função do protocolo DNS (Domain Name System). Já a conversão de um endereço IP em um endereço físico (MAC) da interface de rede é função do protocolo ARP (Address Resolution Protocol).","regraMental":"IP = endereço lógico. DNS = nome → IP. ARP = IP → MAC (endereço físico)."},"comentario":{"resolucao":"CERTO. O endereço IP é um endereço lógico que identifica um dispositivo na rede. A conversão de nomes de domínio em endereços IP é realizada pelo protocolo DNS, enquanto a conversão de endereços IP em endereços físicos (MAC) é realizada pelo protocolo ARP.","fundamento":"Doutrina de Informática — Internet e Redes (endereço IP, DNS, ARP).","macete":"IP: lógico. DNS: nome→IP. ARP: IP→MAC. Três coisas diferentes, não confundir.","erroComum":"Atribuir ao endereço IP, em vez de ao DNS, a função de converter nomes de domínio.","comoBancaPensa":"Item 'limpo' que exige a distinção precisa entre três conceitos de redes frequentemente confundidos."}},"TI-105":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que o IP é um endereço lógico (não um protocolo conversor), e que essa conversão é feita por DNS e ARP.","mede":"Informática — Internet e Redes (endereço IP, DNS, ARP).","pegadinhaDesc":"A banca transforma o endereço IP em um 'protocolo conversor', função que na verdade pertence ao DNS e ao ARP.","ondeErra":"Confunde o endereço IP (identificador lógico) com os protocolos responsáveis pela conversão de nomes/endereços (DNS e ARP).","palavraCritica":"endereço IP é definido como o protocolo responsável pela conversão","tecnica":"O endereço IP não é um protocolo, mas um endereço lógico que identifica um dispositivo na rede. A conversão de nomes de domínio em endereços IP é função do DNS, e a conversão de endereços IP em endereços físicos (MAC) é função do ARP — não do próprio endereço IP.","regraMental":"IP não converte nada — é só um endereço. Quem converte é o DNS (nome) e o ARP (MAC)."},"comentario":{"resolucao":"ERRADO. O endereço IP não é um protocolo, mas um endereço lógico que identifica um dispositivo na rede. A conversão de nomes de domínio em endereços IP é função do DNS, e a conversão de endereços IP em endereços físicos (MAC) é função do ARP — e não do próprio endereço IP.","fundamento":"Doutrina de Informática — Internet e Redes (endereço IP, DNS, ARP).","macete":"IP não é protocolo de conversão — é só o endereço. DNS e ARP é que convertem.","erroComum":"Confundir o endereço IP com os protocolos DNS e ARP, atribuindo-lhe uma função que não é sua.","comoBancaPensa":"Redefine erroneamente o endereço IP como um 'protocolo', atribuindo-lhe funções de DNS e ARP."}},"TI-106":{"cognitivo":{"motivo":"Fixar os três pilares corretamente pareados.","mede":"Segurança da informação — tríade CID.","pegadinhaDesc":"Os três conceitos e suas definições corretamente associados.","ondeErra":"Troca integridade com confidencialidade.","palavraCritica":"não seja alterada indevidamente","tecnica":"Confidencialidade é sobre QUEM VÊ; integridade é sobre NÃO MUDAR; disponibilidade é sobre ESTAR ACESSÍVEL.","regraMental":"CID: quem vê, não muda, está no ar."},"comentario":{"resolucao":"CERTO. São os três pilares clássicos da segurança da informação (tríade CID): confidencialidade (acesso restrito a autorizados), integridade (não alteração indevida, preservando exatidão) e disponibilidade (acesso garantido quando necessário).","fundamento":"Segurança da informação — tríade CID (ISO/IEC 27001).","macete":"CID: quem vê, não muda, está no ar.","erroComum":"Trocar integridade por confidencialidade.","comoBancaPensa":"Definições corretas para punir a rejeição automática."}}});
